INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'My Daily Routine' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'A1', 'Tôi đi ngủ lúc mấy giờ?', '9:00', '10:00', '11:00', '12:00', 'D', 'D', 'Tôi ăn và xem TV cho đến giờ đi ngủ.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Introducing My Family', 'A1', 'My name is Emily. I am 10 years old. I live with my family in a small house. My mom is a teacher. She teaches English at a school. My dad is a doctor. He works at a hospital. I have a little brother named Timmy. He is 5 years old. He likes playing with toys. My family loves eating together. We have dinner every night at 7 o''clock.', 'Vietnamese Translation:
Tên tôi là Emily. Tôi 10 tuổi. Tôi sống cùng gia đình trong một ngôi nhà nhỏ. Mẹ tôi là một giáo viên. Bà ấy dạy tiếng Anh tại một trường học. Bố tôi là một bác sĩ. Anh ấy làm việc tại một bệnh viện. Tôi có một em trai nhỏ tên là Timmy. Anh ấy 5 tuổi. Anh ấy thích chơi với đồ chơi. Gia đình tôi yêu thích ăn uống cùng nhau. Chúng tôi có bữa tối mỗi tối lúc 7 giờ.

Keywords:
family (n): gia đình, teacher (n): giáo viên, doctor (n): bác sĩ, hospital (n): bệnh viện, dinner (n): bữa tối', 20, 5);
