INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Day at the Zoo' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'A1', 'Emma có một ngày tuyệt vời tại sở thú vì sao?', 'Cô thấy nhiều động vật', 'Cô có một thời gian tuyệt vời với gia đình', 'Cô thấy một quảng cáo lớn cho sở thú', 'Tất cả các lý do trên', 'D', 'D', 'Emma có một ngày tuyệt vời tại sở thú vì cô thấy nhiều động vật và có một thời gian tuyệt vời với gia đình.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'My Favorite Hobby', 'A1', 'My favorite hobby is playing soccer. I like playing soccer because it''s fun. I play soccer with my friends every weekend. We go to the park and kick the ball around. Sometimes we play a game and keep score. I like winning, but I also like playing just for fun.', 'Vietnamese Translation:
Hobby yêu thích của tôi là chơi bóng đá. Tôi thích chơi bóng đá vì nó thú vị. Tôi chơi bóng đá với bạn bè của tôi mỗi cuối tuần. Chúng tôi đi đến công viên và đá bóng. Thỉnh thoảng chúng tôi chơi một trận và giữ điểm số. Tôi thích chiến thắng, nhưng tôi cũng thích chơi chỉ vì vui vẻ.

Keywords:
hobby (n): sở thích, soccer (n): bóng đá, fun (adj): thú vị, weekend (n): cuối tuần, park (n): công viên, score (v): giữ điểm số', 20, 5);
