INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Simple Recipe for Pancakes', 'A1', 'Here''s a simple recipe for pancakes. You will need 1 cup of milk, 1 egg, and 1 cup of flour. First, mix the milk and egg together in a bowl. Then, add the flour and mix until it''s smooth. Heat a pan on the stove and put some oil in it. When the oil is hot, pour some of the mixture into the pan. Cook for 2 minutes and then flip the pancake over. Cook for another minute and then it''s ready.', 'Vietnamese Translation:
Dưới đây là công thức làm bánh kếp đơn giản. Bạn cần 1 cốc sữa, 1 quả trứng và 1 cốc bột mì. Trước tiên, trộn sữa và trứng vào một bát. Sau đó, thêm bột mì và trộn cho đến khi hỗn hợp mịn. Nấu một chảo trên bếp và cho một ít dầu vào. Khi dầu nóng, đổ một ít hỗn hợp vào chảo. Nấu trong 2 phút và sau đó lật bánh kếp lại. Nấu thêm 1 phút nữa và nó đã sẵn sàng.

Keywords:
pancake (n): bánh kếp, milk (n): sữa, egg (n): trứng, flour (n): bột mì, mix (v): trộn, heat (v): nấu nóng, oil (n): dầu', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Simple Recipe for Pancakes' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'A1', 'What do we need to make pancakes?', '1 cup of milk and 1 egg', '1 cup of flour and 1 egg', '1 cup of milk and 1 cup of flour', '1 egg and 1 cup of flour', 'C', 'C', 'Chúng ta cần 1 cốc sữa và 1 cốc bột mì để làm bánh kếp.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Simple Recipe for Pancakes' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'A1', 'What do we do first with the milk and egg?', 'Add the flour and mix', 'Heat the pan on the stove', 'Mix the milk and egg together', 'Pour the mixture into the pan', 'C', 'C', 'Chúng ta trộn sữa và trứng cùng nhau trước tiên.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Simple Recipe for Pancakes' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'A1', 'How long do we cook the pancake?', '1 minute on each side', '2 minutes on each side', '1 minute on one side and 2 minutes on the other side', '2 minutes on one side and 1 minute on the other side', 'B', 'B', 'Chúng ta nấu bánh kếp trong 2 phút trên mỗi mặt.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Simple Recipe for Pancakes' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'A1', 'What do we put in the pan before cooking the pancake?', 'Oil', 'Butter', 'Water', 'Syrup', 'A', 'A', 'Chúng ta cho dầu vào chảo trước khi nấu bánh kếp.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Simple Recipe for Pancakes' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'A1', 'What is the final step in making pancakes?', 'Mix the milk and egg', 'Heat the pan on the stove', 'Pour the mixture into the pan', 'Cook for another minute', 'D', 'D', 'Bước cuối cùng trong việc làm bánh kếp là nấu thêm 1 phút nữa.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Welcome to My House', 'A1', 'I live in a small house with my family. My house has two bedrooms, a living room, and a kitchen. My bedroom is on the second floor. My family and I like to spend time together in the living room. We watch TV and play games. My mom cooks delicious food in the kitchen. I like to help her sometimes.', 'Vietnamese Translation:
Tôi sống trong một ngôi nhà nhỏ cùng với gia đình. Ngôi nhà của tôi có hai phòng ngủ, một phòng khách và một bếp. Phòng ngủ của tôi nằm trên tầng hai. Gia đình tôi và tôi thích dành thời gian bên nhau trong phòng khách. Chúng tôi xem TV và chơi trò chơi. Mẹ tôi nấu ăn ngon trong bếp. Tôi thích giúp mẹ mình đôi khi.

Keywords:
home (n): nhà, family (n): gia đình, bedroom (n): phòng ngủ, living room (n): phòng khách, kitchen (n): bếp, floor (n): tầng, mom (n): mẹ', 20, 5);
