INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Job Ad for a Cashier', 'A1', 'We are looking for a friendly cashier to work in our store. The job involves helping customers, handling money, and working with a team. You will be working 20 hours a week, from 10am to 6pm, Monday to Saturday. If you are interested, please send your CV and a short letter explaining why you would be good for the job.', 'Vietnamese Translation:
Chúng tôi đang tìm kiếm một nhân viên thu ngân thân thiện để làm việc tại cửa hàng của chúng tôi. Công việc bao gồm giúp đỡ khách hàng, quản lý tiền bạc và làm việc với một đội ngũ. Bạn sẽ làm việc 20 giờ một tuần, từ 10 giờ sáng đến 6 giờ chiều, từ thứ hai đến thứ sáu. Nếu bạn quan tâm, xin vui lòng gửi CV và một bức thư ngắn giải thích tại sao bạn sẽ phù hợp với công việc này.

Keywords:
cashier (n): nhân viên thu ngân, job (n): công việc, team (n): đội ngũ, CV (n): sơ yếu lý lịch, letter (n): bức thư', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Job Ad for a Cashier' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'A1', 'What is the job of the cashier?', 'Helping customers and handling money', 'Working alone and making decisions', 'Selling products and managing stock', 'Managing the store and employees', 'A', 'A', 'Công việc của nhân viên thu ngân bao gồm giúp đỡ khách hàng và quản lý tiền bạc.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Job Ad for a Cashier' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'A1', 'How many hours a week will the cashier work?', '10 hours', '20 hours', '30 hours', '40 hours', 'B', 'B', 'Nhân viên thu ngân sẽ làm việc 20 giờ một tuần.');
