INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Job Ad for a Cashier' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'A1', 'Why is the employer looking for a friendly cashier?', 'Because they want to make money', 'Because they want to help customers', 'Because they want to work with a team', 'Because they want to have fun', 'B', 'B', 'Chủ nhân đang tìm kiếm một nhân viên thu ngân thân thiện vì họ muốn giúp đỡ khách hàng.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Classroom Rules Announcement', 'A1', 'Good morning, students! Today, we will be discussing the classroom rules. Please listen carefully. We must be quiet in the classroom. We must not talk to each other during lessons. We must raise our hands to ask questions. We must respect our teacher and our classmates. Let''s work together to make our classroom a happy and safe place.', 'Vietnamese Translation:
Chào buổi sáng, học sinh! Hôm nay, chúng ta sẽ thảo luận về các quy tắc lớp học. Vui lòng lắng nghe cẩn thận. Chúng ta phải im lặng trong lớp học. Chúng ta không được nói chuyện với nhau trong các bài học. Chúng ta phải nâng tay lên để hỏi câu hỏi. Chúng ta phải tôn trọng giáo viên và các bạn học sinh. Hãy cùng nhau làm cho lớp học của chúng ta trở thành một nơi hạnh phúc và an toàn.

Keywords:
classroom (n): lớp học, rules (n): quy tắc, quiet (adj): im lặng, respect (v): tôn trọng, teacher (n): giáo viên', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Classroom Rules Announcement' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'A1', 'What must students do in the classroom?', 'Talk to each other during lessons', 'Raise their hands to ask questions', 'Be quiet in the classroom', 'Leave the classroom', 'C', 'C', 'Học sinh phải im lặng trong lớp học.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Classroom Rules Announcement' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'A1', 'Why must students respect their teacher and classmates?', 'Because they are friends', 'Because they are in the same class', 'Because they are in a classroom', 'Because they want to make the classroom a happy and safe place', 'D', 'D', 'Học sinh phải tôn trọng giáo viên và các bạn học sinh vì họ muốn tạo ra một lớp học hạnh phúc và an toàn.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Classroom Rules Announcement' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'A1', 'What will happen if students talk to each other during lessons?', 'They will get a prize', 'They will get a punishment', 'They will get a break', 'They will get a gift', 'B', 'B', 'Nếu học sinh nói chuyện với nhau trong các bài học, họ sẽ bị trừng phạt.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Classroom Rules Announcement' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'A1', 'Why must students raise their hands to ask questions?', 'Because they want to get attention', 'Because they want to ask a question', 'Because they want to make a friend', 'Because they want to learn something new', 'B', 'B', 'Học sinh phải nâng tay lên để hỏi câu hỏi vì họ muốn hỏi một câu hỏi.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Classroom Rules Announcement' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'A1', 'What is the main idea of the announcement?', 'To talk about the classroom rules', 'To discuss the school schedule', 'To introduce the new teacher', 'To announce the school holiday', 'A', 'A', 'Mục tiêu chính của thông báo này là thảo luận về các quy tắc lớp học.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Meet My Pet', 'A1', 'My name is Emily. I have a pet dog. His name is Max. Max is a golden retriever. He is very friendly. Max loves to play with me. We play fetch in the park. Max is very good at catching balls. He is also very good at sitting. I give him treats when he sits. Max is a happy dog. He loves me very much.', 'Vietnamese Translation:
Tên tôi là Emily. Tôi có một con chó. Tên của nó là Max. Max là một con chó golden retriever. Nó rất thân thiện. Max thích chơi với tôi. Chúng tôi chơi tìm bóng trong công viên. Max rất giỏi trong việc bắt bóng. Nó cũng rất giỏi trong việc ngồi. Tôi cho nó thưởng khi nó ngồi. Max là một con chó hạnh phúc. Nó yêu tôi rất nhiều.

Keywords:
pet (n): thú cưng, dog (n): chó, friendly (adj): thân thiện, park (n): công viên, fetch (v): chơi tìm bóng, treat (n): thưởng', 20, 5);
