INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'My Favorite Season', 'A1', 'I love the spring season. The weather is warm and sunny. Flowers start to bloom in the garden. My favorite flower is the cherry blossom. It''s so beautiful and fragrant. I like to walk in the park and see the flowers. It makes me happy.', 'Vietnamese Translation:
Tôi yêu mùa xuân. Thời tiết ấm áp và nắng đẹp. Hoa bắt đầu nở trong vườn. Hoa anh đào là hoa yêu thích của tôi. Nó đẹp và thơm ngào ngạt. Tôi thích đi dạo trong công viên và thấy hoa. Nó làm tôi hạnh phúc.

Keywords:
season (n): mùa, warm (adj): ấm áp, sunny (adj): nắng đẹp, bloom (v): nở hoa, fragrant (adj): thơm ngào ngạt, park (n): công viên', 20, 5);
