INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Review of a Local Café' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'A2', 'What did the writer think of the café?', 'He thought it was too expensive', 'He thought it was too noisy', 'He thought it was a nice place to relax', 'He thought it was a bad place to eat', 'C', 'C', 'Tác giả đã nghĩ rằng đó là một nơi tuyệt vời để thư giãn.');
