INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Safety Instructions for Fire Drills' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'A2', 'Where should you go after you are outside?', 'The nearest exit', 'The assembly point', 'The fire department', 'The elevator', 'B', 'B', 'Một khi bạn đã ra ngoài, hãy đi đến điểm tập trung.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Safety Instructions for Fire Drills' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'A2', 'What should you do if you are in a room with no windows?', 'Go to the nearest exit', 'Find another way out', 'Call the fire department', 'Wait for the firefighters to arrive', 'B', 'B', 'Nếu bạn đang trong một phòng mà không có cửa sổ, hãy tìm một lối thoát khác.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Weekend Flight Delay Announcement', 'A2', 'Dear passengers, we regret to inform you that your flight to Tokyo has been delayed due to bad weather. The new departure time is 2:00 PM instead of 12:00 PM. We apologize for the inconvenience and appreciate your patience. You can check the flight status on our website or mobile app. Thank you for your understanding.', 'Vietnamese Translation:
Kính gửi hành khách, chúng tôi xin lỗi vì phải thông báo rằng chuyến bay của quý khách đến Tokyo đã bị chậm do thời tiết xấu. Giờ khởi hành mới là 2:00 chiều thay vì 12:00 trưa. Chúng tôi xin lỗi vì bất tiện và đánh giá cao sự kiên nhẫn của quý khách. Quý khách có thể kiểm tra tình trạng chuyến bay trên trang web hoặc ứng dụng di động của chúng tôi. Cảm ơn sự hiểu biết của quý khách.

Keywords:
flight (n): chuyến bay, delay (v): chậm, weather (n): thời tiết, website (n): trang web, mobile app (n): ứng dụng di động', 20, 5);
