INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Conversation about Weekend Plans', 'A2', 'It''s Friday evening and Sarah is talking to her friend Emily on the phone.', 'Vietnamese Translation:
Vào buổi tối thứ Sáu, Sarah đang trò chuyện với bạn thân Emily qua điện thoại.

Keywords:
