INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Conversation about Weekend Plans' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'A2', 'What is Sarah doing?', 'She is going to the movies.', 'She is talking to her friend Emily on the phone.', 'She is watching TV.', 'She is reading a book.', 'B', 'B', 'Vào buổi tối thứ Sáu, Sarah đang trò chuyện với bạn thân Emily qua điện thoại.');
