INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Conversation about Weekend Plans' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'A2', 'How does Sarah usually commute to work?', 'She walks to work.', 'She takes the bus to work.', 'She drives to work.', 'She takes the train to work.', 'C', 'C', 'Sarah thường đi làm bằng xe hơi.');
