INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Lost Wallet Notice in Office', 'A2', 'Lost Wallet Notice in Office

To all staff,

I lost my wallet in the office yesterday. It contains my ID, credit cards, and some cash. If anyone finds it, please return it to the reception desk.

Thank you.', 'Vietnamese Translation:
Thông báo mất ví trong văn phòng

Đối với tất cả nhân viên,

Tôi đã mất ví của mình trong văn phòng ngày hôm qua. Nó chứa ID, thẻ tín dụng và một số tiền mặt. Nếu ai đó tìm thấy nó, vui lòng trả lại nó cho bộ phận tiếp tân.

Cảm ơn.

Keywords:
lost (v): mất, wallet (n): ví tiền, ID (n): chứng minh nhân dân, credit card (n): thẻ tín dụng, cash (n): tiền mặt, reception desk (n): bộ phận tiếp tân', 20, 5);
