INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Learn English with Us' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'A2', 'What levels of English do the classes cater to?', 'Only beginner level', 'Only advanced level', 'All levels, from beginner to advanced', 'No levels', 'C', 'C', 'Các lớp học này cung cấp cho tất cả các cấp độ, từ sơ cấp đến nâng cao.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Learn English with Us' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'A2', 'What is the tone of the advertisement?', 'Serious', 'Friendly', 'Entertaining', 'Scary', 'B', 'B', 'Tone của quảng cáo này là thân thiện.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Learn English with Us' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'A2', 'What should you do according to the advertisement?', 'Wait for a while', 'Contact the school', 'Go to the store', 'Watch TV', 'B', 'B', 'Theo quảng cáo, bạn nên liên hệ với trường ngay hôm nay để đăng ký một lớp học.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Company Holiday Notice', 'A2', 'Dear employees, we are pleased to announce that our company will be closed for the summer holiday from August 1st to August 31st. During this time, all employees will receive a paid vacation. We will reopen on September 1st. Please note that the office will be closed on July 4th for Independence Day. If you have any urgent matters, please contact your supervisor. Thank you for your understanding.', 'Vietnamese Translation:
Kính gửi các nhân viên, chúng tôi rất hân hạnh thông báo rằng công ty sẽ đóng cửa trong kỳ nghỉ hè từ ngày 1 tháng 8 đến ngày 31 tháng 8. Trong thời gian này, tất cả nhân viên sẽ nhận được nghỉ phép có lương. Chúng tôi sẽ mở cửa trở lại vào ngày 1 tháng 9. Xin lưu ý rằng văn phòng sẽ đóng cửa vào ngày 4 tháng 7 để kỷ niệm Ngày độc lập. Nếu bạn có bất kỳ vấn đề cấp bách nào, xin liên hệ với người quản lý của bạn. Cảm ơn sự hiểu biết của bạn.

Keywords:
holiday (n): kỳ nghỉ, vacation (n): nghỉ phép, supervisor (n): người quản lý, urgent (adj): cấp bách, office (n): văn phòng, announcement (n): thông báo, employee (n): nhân viên', 20, 5);
