INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Client Feedback Report Summary', 'B1', 'The client feedback report for the marketing campaign is now available. According to the report, the campaign was successful in reaching 80% of the target audience. However, there were some issues with the website''s user interface, which caused 20% of the users to drop out. The report also suggests that the campaign''s social media strategy was effective in engaging the audience, but the email marketing strategy was less successful. Overall, the campaign''s results were mixed, and further analysis is needed to identify areas for improvement.', 'Vietnamese Translation:
Báo cáo phản hồi của khách hàng cho chiến dịch tiếp thị đã sẵn sàng. Theo báo cáo, chiến dịch đã thành công trong việc tiếp cận 80% đối tượng mục tiêu. Tuy nhiên, có một số vấn đề với giao diện người dùng của trang web, khiến 20% người dùng bỏ cuộc. Báo cáo cũng đề xuất rằng chiến lược tiếp thị trên mạng xã hội của chiến dịch đã hiệu quả trong việc thu hút sự chú ý của đối tượng, nhưng chiến lược tiếp thị qua email không thành công. Tóm lại, kết quả của chiến dịch là hỗn hợp và cần phải phân tích thêm để xác định các khu vực cần cải thiện.

Keywords:
marketing campaign (n): chiến dịch tiếp thị, target audience (n): đối tượng mục tiêu, user interface (n): giao diện người dùng, email marketing (n): tiếp thị qua email', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Client Feedback Report Summary' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'B1', 'What percentage of the target audience was reached by the marketing campaign?', '60%', '80%', '90%', '70%', 'B', 'B', 'Báo cáo cho biết chiến dịch tiếp thị đã thành công trong việc tiếp cận 80% đối tượng mục tiêu.');
