INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Business Trip Expense Reimbursement Procedure', 'B1', 'Dear All,

I am writing to inform you of the new business trip expense reimbursement procedure. As of today, all employees are required to submit their expense reports within 5 working days of returning from a business trip.

To facilitate the reimbursement process, please ensure that your expense reports are complete and accurate. This includes attaching all relevant receipts and invoices.

If you have any questions or concerns regarding the new procedure, please do not hesitate to contact the finance department.

Thank you for your cooperation.

Best regards,
[Your Name]', 'Vietnamese Translation:
Kính gửi tất cả,

Tôi viết thư này để thông báo về thủ tục hoàn trả chi phí công tác mới. Từ hôm nay, tất cả nhân viên đều phải nộp báo cáo chi phí công tác trong vòng 5 ngày làm việc sau khi trở về từ công tác.

Để thuận tiện cho quá trình hoàn trả, vui lòng đảm bảo rằng báo cáo chi phí công tác của bạn đầy đủ và chính xác. Điều này bao gồm việc đính kèm tất cả hóa đơn và chứng từ liên quan.

Nếu bạn có bất kỳ câu hỏi hoặc mối quan tâm nào về thủ tục mới, vui lòng liên hệ với bộ phận tài chính.

Cảm ơn sự hợp tác của bạn.

Trân trọng,
[Tên của bạn]

Keywords:
business trip (n): chuyến công tác, expense report (n): báo cáo chi phí, reimbursement (n): hoàn trả, finance department (n): bộ phận tài chính, receipt (n): hóa đơn, invoice (n): hóa đơn, working day (n): ngày làm việc', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Business Trip Expense Reimbursement Procedure' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'B1', 'Theo thủ tục mới, nhân viên cần nộp báo cáo chi phí công tác trong bao lâu sau khi trở về từ công tác?', '3 ngày làm việc', '5 ngày làm việc', '7 ngày làm việc', '10 ngày làm việc', 'B', 'B', 'Theo thư, nhân viên cần nộp báo cáo chi phí công tác trong 5 ngày làm việc sau khi trở về từ công tác.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Business Trip Expense Reimbursement Procedure' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'B1', 'Thủ tục hoàn trả chi phí công tác mới bao gồm việc đính kèm hóa đơn và chứng từ liên quan.', 'Đúng', 'Sai', 'Không rõ', 'Không liên quan', 'A', 'A', 'Theo thư, thủ tục hoàn trả chi phí công tác mới bao gồm việc đính kèm hóa đơn và chứng từ liên quan.');
