INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Business Trip Expense Reimbursement Procedure' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B1', 'Thủ tục mới có hiệu lực từ ngày nào?', 'Hôm nay', 'Ngày mai', 'Ngày sau', 'Không rõ', 'A', 'A', 'Theo thư, thủ tục mới có hiệu lực từ hôm nay.');
