INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Product Recall Notice' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'B1', 'Công ty đã xin lỗi vì gì?', 'Do sản phẩm không đáp ứng được tiêu chuẩn chất lượng', 'Do sản phẩm chứa chì, gây rủi ro sức khỏe', 'Do sản phẩm không được sản xuất đúng quy trình', 'Do sản phẩm không được bán đúng giá', 'B', 'B', 'Công ty đã xin lỗi vì sản phẩm chứa chì, gây rủi ro sức khỏe cho khách hàng.');
