INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Annual Office Supplies Audit Memo' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'B1', 'Ai có thể liên hệ với người gửi email nếu có bất kỳ câu hỏi hoặc mối quan tâm nào về kiểm toán?', 'Chỉ người quản lý', 'Chỉ người lao động', 'Tất cả mọi người', 'Người gửi email', 'C', 'C', 'Nếu bạn có bất kỳ câu hỏi hoặc mối quan tâm nào về kiểm toán, xin đừng ngần ngại liên hệ với người gửi email.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Contract Negotiation via Email', 'B1', 'Dear Mr. Tanaka,

I hope this email finds you well. I am writing to follow up on our previous discussion regarding the contract for the supply of electronic components to your company. As we previously agreed, the total price for the order is $100,000, with a 10% discount for the first-time purchase.

However, after reviewing the contract, I noticed that the payment terms are not clearly stated. Could you please clarify the payment schedule and the method of payment? We would like to ensure that the payment is made in a timely manner to avoid any delays in the production process.

Additionally, I would like to request a copy of the invoice for our records. Please let me know if this is feasible.

Thank you for your prompt attention to this matter. I look forward to hearing back from you soon.

Best regards,
Emily', 'Vietnamese Translation:
Kính gửi ông Tanaka,

Hy vọng email này đến với ông trong tình trạng tốt. Tôi viết thư này để theo dõi lại cuộc thảo luận trước đó về hợp đồng cung cấp các linh kiện điện tử cho công ty của ông. Như chúng ta đã đồng ý trước đó, tổng giá trị của đơn hàng là 100.000 USD, với mức giảm 10% cho đơn hàng lần đầu tiên.

Tuy nhiên, sau khi xem xét hợp đồng, tôi nhận thấy rằng các điều khoản thanh toán không được rõ ràng. Ông có thể giải thích lịch trình thanh toán và phương thức thanh toán không? Chúng tôi muốn đảm bảo rằng thanh toán được thực hiện một cách kịp thời để tránh bất kỳ trì hoãn nào trong quá trình sản xuất.

Ngoài ra, tôi muốn yêu cầu một bản sao hóa đơn cho mục đích lưu trữ. Ông có thể cho tôi biết điều này có thể thực hiện được không?

Cảm ơn sự chú ý nhanh chóng của ông. Tôi mong chờ được nghe lại từ ông sớm.

Trân trọng,
Emily

Keywords:
contract (n): hợp đồng, negotiation (n): đàm phán, payment (n): thanh toán, invoice (n): hóa đơn, production (n): sản xuất, discount (n): giảm giá, schedule (n): lịch trình', 20, 5);
