INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Company Policy on Using Personal Laptops', 'B1', 'As of today, our company will be implementing a new policy regarding the use of personal laptops in the workplace. According to this policy, all employees are allowed to bring their personal laptops to work, but they must be used for work-related purposes only. This means that personal emails, social media, and online shopping are strictly prohibited during work hours. Employees who fail to comply with this policy may face disciplinary action, up to and including termination of employment. We understand that this may cause some inconvenience, but we believe that this policy will help to increase productivity and reduce distractions in the workplace. If you have any questions or concerns, please do not hesitate to reach out to your supervisor or HR representative.', 'Vietnamese Translation:
Từ hôm nay, công ty chúng tôi sẽ thực hiện một chính sách mới liên quan đến việc sử dụng máy tính xách tay cá nhân trong nơi làm việc. Theo chính sách này, tất cả nhân viên đều được phép mang máy tính xách tay cá nhân đến nơi làm việc, nhưng chúng phải được sử dụng cho mục đích làm việc chỉ. Điều này có nghĩa là các email cá nhân, mạng xã hội và mua sắm trực tuyến đều bị cấm trong giờ làm việc. Nhân viên nào không tuân thủ chính sách này sẽ phải đối mặt với hành động kỷ luật, bao gồm cả việc sa thải. Chúng tôi hiểu rằng điều này có thể gây ra một số bất tiện, nhưng chúng tôi tin rằng chính sách này sẽ giúp tăng năng suất và giảm sự phân tâm trong nơi làm việc. Nếu bạn có bất kỳ câu hỏi hoặc mối quan tâm nào, xin vui lòng liên hệ với người quản lý hoặc đại diện nhân sự của bạn.

Keywords:
company policy (n): chính sách công ty, laptop (n): máy tính xách tay, work-related (adj): liên quan đến công việc, productivity (n): năng suất, distraction (n): sự phân tâm', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Company Policy on Using Personal Laptops' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'B1', 'Theo chính sách mới, nhân viên được phép sử dụng máy tính xách tay cá nhân cho mục đích gì?', 'Mục đích cá nhân', 'Mục đích làm việc', 'Mục đích giải trí', 'Mục đích kinh doanh', 'B', 'B', 'Chính sách mới chỉ cho phép sử dụng máy tính xách tay cá nhân cho mục đích làm việc.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Company Policy on Using Personal Laptops' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'B1', 'Nếu nhân viên không tuân thủ chính sách mới, họ sẽ phải đối mặt với hành động kỷ luật nào?', 'Kỷ luật nhẹ', 'Kỷ luật trung bình', 'Kỷ luật nặng', 'Sa thải', 'D', 'D', 'Chính sách mới cho biết nhân viên không tuân thủ sẽ phải đối mặt với hành động kỷ luật, bao gồm cả việc sa thải.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Company Policy on Using Personal Laptops' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'B1', 'Chính sách mới nhằm mục đích gì?', 'Tăng năng suất', 'Giảm sự phân tâm', 'Tăng thu nhập', 'Tăng cường kỷ luật', 'A', 'A', 'Chính sách mới nhằm mục đích tăng năng suất và giảm sự phân tâm trong nơi làm việc.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Company Policy on Using Personal Laptops' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B1', 'Nếu bạn có câu hỏi hoặc mối quan tâm, bạn nên liên hệ với ai?', 'Người quản lý', 'Đại diện nhân sự', 'Bất kỳ ai', 'Không ai', 'B', 'B', 'Chính sách mới cho biết nếu bạn có câu hỏi hoặc mối quan tâm, bạn nên liên hệ với người quản lý hoặc đại diện nhân sự.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Company Policy on Using Personal Laptops' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'B1', 'Chính sách mới có hiệu lực từ ngày nào?', 'Hôm nay', 'Ngày mai', 'Tuần tới', 'Tháng tới', 'A', 'A', 'Chính sách mới có hiệu lực từ hôm nay.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Customer Service Inquiry Response', 'B1', 'Dear Customer Service Team,

I recently purchased a new laptop from your company and I am experiencing some issues with the keyboard. The keys are not registering properly and I am having trouble typing.

I would like to request a replacement keyboard or a refund for the laptop. Could you please let me know what steps I need to take to resolve this issue?

Thank you for your assistance.

Sincerely,
[Your Name]', 'Vietnamese Translation:
Kính gửi Đội ngũ Dịch vụ Khách hàng,

Tôi đã mua một chiếc laptop mới từ công ty của bạn và tôi đang gặp một số vấn đề với bàn phím. Các phím không được ghi nhận đúng và tôi đang gặp khó khăn khi gõ văn bản.

Tôi muốn yêu cầu một bàn phím thay thế hoặc một khoản hoàn tiền cho laptop. Xin vui lòng cho tôi biết các bước tôi cần thực hiện để giải quyết vấn đề này?

Cảm ơn sự hỗ trợ của bạn.

Trân trọng,
[Tên của bạn]

Keywords:
