INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'The Basics of Digital Marketing', 'B1', 'Digital marketing is a form of marketing that uses digital channels such as search engines, social media, email, and websites to reach customers. It involves creating and sharing content that is relevant and valuable to your target audience, with the goal of driving website traffic, generating leads, and increasing sales. There are several key components of digital marketing, including search engine optimization (SEO), pay-per-click advertising (PPC), social media marketing, email marketing, and content marketing. By understanding these components and how they work together, businesses can create a comprehensive digital marketing strategy that helps them achieve their goals. For example, a company that sells outdoor gear might use SEO to optimize its website for search engines, PPC to run targeted ads on Google, and social media marketing to engage with customers on platforms like Facebook and Instagram.', 'Vietnamese Translation:
Marketing số là một hình thức tiếp thị sử dụng các kênh số như các công cụ tìm kiếm, mạng xã hội, email và trang web để tiếp cận khách hàng. Nó bao gồm việc tạo và chia sẻ nội dung có liên quan và có giá trị đối với đối tượng mục tiêu của bạn, với mục tiêu là tăng lưu lượng truy cập trang web, tạo ra các cơ hội kinh doanh và tăng doanh số. Có một số thành phần chính của marketing số, bao gồm tối ưu hóa công cụ tìm kiếm (SEO), quảng cáo trả tiền mỗi lần nhấp chuột (PPC), tiếp thị trên mạng xã hội, tiếp thị qua email và tiếp thị nội dung. Bằng cách hiểu các thành phần này và cách chúng hoạt động cùng nhau, các doanh nghiệp có thể tạo một chiến lược marketing số toàn diện giúp họ đạt được mục tiêu của mình.

Keywords:
digital marketing: tiếp thị số, search engine optimization: tối ưu hóa công cụ tìm kiếm, pay-per-click advertising: quảng cáo trả tiền mỗi lần nhấp chuột, social media marketing: tiếp thị trên mạng xã hội, email marketing: tiếp thị qua email, content marketing: tiếp thị nội dung', 20, 6);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Basics of Digital Marketing' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'B1', 'What is digital marketing?', 'A form of marketing that uses traditional channels such as print and television.', 'A form of marketing that uses digital channels such as search engines, social media, email, and websites.', 'A form of marketing that only uses social media.', 'A form of marketing that only uses email.', 'B', 'B', 'Marketing số là một hình thức tiếp thị sử dụng các kênh số như các công cụ tìm kiếm, mạng xã hội, email và trang web để tiếp cận khách hàng.');
