INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Basics of Digital Marketing' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B1', 'What is an example of a company that uses digital marketing?', 'A company that sells outdoor gear.', 'A company that sells clothing.', 'A company that sells electronics.', 'A company that sells food.', 'A', 'A', 'Một ví dụ về một công ty sử dụng marketing số là một công ty bán đồ ngoài trời.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Basics of Digital Marketing' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'B1', 'What is SEO?', 'Tối ưu hóa công cụ tìm kiếm.', 'Quảng cáo trả tiền mỗi lần nhấp chuột.', 'Tiếp thị trên mạng xã hội.', 'Tiếp thị qua email.', 'A', 'A', 'SEO là tối ưu hóa công cụ tìm kiếm.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Basics of Digital Marketing' ORDER BY id DESC LIMIT 1), 6, 'MULTIPLE_CHOICE', 'B1', 'What is PPC?', 'Quảng cáo trả tiền mỗi lần nhấp chuột.', 'Tối ưu hóa công cụ tìm kiếm.', 'Tiếp thị trên mạng xã hội.', 'Tiếp thị qua email.', 'A', 'A', 'PPC là quảng cáo trả tiền mỗi lần nhấp chuột.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Review of ''The Art of Leadership''', 'B1', 'The Art of Leadership is a book written by a renowned business expert. The book provides insights into the qualities and skills required to become a successful leader. According to the author, a good leader must possess strong communication skills, be able to motivate their team members, and make informed decisions. The book also emphasizes the importance of adaptability, resilience, and empathy in leadership. The author shares real-life examples of successful leaders who have demonstrated these qualities and skills. Overall, the book is a valuable resource for anyone looking to improve their leadership skills and become a more effective leader.', 'Vietnamese Translation:
The Art of Leadership là một cuốn sách được viết bởi một chuyên gia kinh doanh nổi tiếng. Cuốn sách cung cấp những hiểu biết về các phẩm chất và kỹ năng cần thiết để trở thành một nhà lãnh đạo thành công. Theo tác giả, một nhà lãnh đạo tốt phải có kỹ năng giao tiếp mạnh mẽ, có thể khích lệ thành viên đội ngũ và đưa ra quyết định thông minh. Cuốn sách cũng nhấn mạnh tầm quan trọng của khả năng thích nghi, sự kiên cường và sự đồng cảm trong lãnh đạo. Tác giả chia sẻ những ví dụ thực tế về các nhà lãnh đạo thành công đã thể hiện những phẩm chất và kỹ năng này. Tổng thể, cuốn sách là một nguồn tài nguyên giá trị cho bất kỳ ai muốn cải thiện kỹ năng lãnh đạo và trở thành một nhà lãnh đạo hiệu quả hơn.

Keywords:
leadership (n): lãnh đạo, communication (n): giao tiếp, motivation (n): khích lệ, decision (n): quyết định, adaptability (n): khả năng thích nghi, resilience (n): sự kiên cường, empathy (n): sự đồng cảm', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Review of ''The Art of Leadership''' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'B1', 'What is the main topic of the book ''The Art of Leadership''?', 'The qualities and skills required to become a successful leader', 'The importance of communication in business', 'The role of motivation in team management', 'The benefits of adaptability in leadership', 'A', 'A', 'Cuốn sách ''The Art of Leadership'' chủ yếu đề cập đến các phẩm chất và kỹ năng cần thiết để trở thành một nhà lãnh đạo thành công.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Review of ''The Art of Leadership''' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'B1', 'What is one of the key skills required to become a successful leader, according to the author?', 'Strong communication skills', 'Ability to make informed decisions', 'Ability to motivate team members', 'Ability to adapt to new situations', 'A', 'A', 'Theo tác giả, một trong những kỹ năng quan trọng cần có để trở thành một nhà lãnh đạo thành công là kỹ năng giao tiếp mạnh mẽ.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Review of ''The Art of Leadership''' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'B1', 'What is the author''s approach to discussing leadership in the book?', 'Theoretical and abstract', 'Practical and real-life examples', 'Historical and comparative', 'Philosophical and introspective', 'B', 'B', 'Tác giả sử dụng những ví dụ thực tế để thảo luận về lãnh đạo trong cuốn sách.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Review of ''The Art of Leadership''' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B1', 'What is one of the benefits of being a resilient leader, according to the author?', 'Ability to adapt to new situations', 'Ability to motivate team members', 'Ability to make informed decisions', 'Ability to handle stress and pressure', 'D', 'D', 'Theo tác giả, một trong những lợi ích của việc trở thành một nhà lãnh đạo kiên cường là khả năng xử lý căng thẳng và áp lực.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Review of ''The Art of Leadership''' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'B1', 'What is the overall value of the book ''The Art of Leadership''?', 'A comprehensive guide to business management', 'A valuable resource for improving leadership skills', 'A historical account of leadership development', 'A philosophical exploration of leadership', 'B', 'B', 'Tổng thể, cuốn sách ''The Art of Leadership'' là một nguồn tài nguyên giá trị cho bất kỳ ai muốn cải thiện kỹ năng lãnh đạo.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Office Expansion Plan Announcement', 'B1', 'Dear valued employees, we are pleased to announce that our company will be expanding its office space to accommodate our growing team. The new office will be located in a nearby building and will offer more amenities and services to enhance your work experience. The expansion plan includes the addition of new meeting rooms, a state-of-the-art gym, and a cafeteria serving a variety of healthy meals. We believe that this expansion will not only improve our working conditions but also boost our productivity and morale. The new office is expected to be completed by the end of the year, and we will keep you updated on the progress. Thank you for your hard work and dedication to our company. We look forward to seeing you in our new office soon.', 'Vietnamese Translation:
Kính gửi các nhân viên quý giá, chúng tôi rất hân hạnh thông báo rằng công ty của chúng tôi sẽ mở rộng không gian văn phòng để đáp ứng đội ngũ nhân viên đang phát triển. Văn phòng mới sẽ được đặt tại tòa nhà gần đó và sẽ cung cấp nhiều tiện ích và dịch vụ để nâng cao trải nghiệm làm việc của bạn. Kế hoạch mở rộng bao gồm việc thêm phòng họp mới, phòng tập thể dục hiện đại và nhà ăn phục vụ nhiều món ăn lành mạnh. Chúng tôi tin rằng mở rộng này không chỉ cải thiện điều kiện làm việc mà còn tăng cường năng suất và tinh thần của chúng tôi. Văn phòng mới dự kiến sẽ hoàn thành vào cuối năm nay và chúng tôi sẽ cập nhật bạn về tiến độ. Cảm ơn sự cố gắng và sự tận tâm của bạn đối với công ty của chúng tôi. Chúng tôi mong chờ được gặp bạn trong văn phòng mới sớm.

Keywords:
expansion (n): mở rộng, office (n): văn phòng, amenities (n): tiện ích, services (n): dịch vụ, productivity (n): năng suất, morale (n): tinh thần', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Office Expansion Plan Announcement' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'B1', 'Văn phòng mới sẽ được đặt tại đâu?', 'Một tòa nhà gần đó', 'Một tòa nhà xa hơn', 'Một tòa nhà khác', 'Không có thông tin', 'A', 'A', 'Văn phòng mới sẽ được đặt tại tòa nhà gần đó để thuận tiện cho nhân viên.');
