INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Office Expansion Plan Announcement' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B1', 'Mở rộng văn phòng sẽ mang lại lợi ích gì cho nhân viên?', 'Tăng cường năng suất và tinh thần', 'Cải thiện điều kiện làm việc', 'Tăng lương và thưởng', 'Không có lợi ích', 'A', 'A', 'Mở rộng văn phòng sẽ mang lại lợi ích tăng cường năng suất và tinh thần cho nhân viên.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Office Expansion Plan Announcement' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'B1', 'Công ty sẽ làm gì để cập nhật nhân viên về tiến độ?', 'Gửi email hàng tuần', 'Gửi email hàng tháng', 'Cập nhật trên trang web công ty', 'Không có thông tin', 'C', 'C', 'Công ty sẽ cập nhật nhân viên về tiến độ trên trang web công ty.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Employee of the Month', 'B1', 'Dear colleagues, we are pleased to announce that Emily Chen has been chosen as our Employee of the Month for April. Emily has been with our company for three years and has consistently demonstrated exceptional teamwork and dedication to her work. She is always willing to lend a hand and has been a valuable asset to our team. Emily''s hard work and commitment to excellence have not gone unnoticed, and we are grateful to have her on our team. Please join us in congratulating Emily on this well-deserved recognition.', 'Vietnamese Translation:
Kính gửi đồng nghiệp, chúng tôi rất hân hạnh thông báo rằng Emily Chen đã được chọn là Nhân viên tháng của tháng 4. Emily đã làm việc với công ty chúng tôi trong ba năm và đã luôn thể hiện tinh thần đồng đội và sự tận tâm trong công việc. Cô luôn sẵn sàng giúp đỡ và đã trở thành một tài sản quý giá cho đội ngũ của chúng tôi. Sự cố gắng và cam kết của Emily không thể không được chú ý, và chúng tôi rất biết ơn vì đã có cô trong đội ngũ của chúng tôi. Hãy cùng chúng tôi chúc mừng Emily vì sự công nhận xứng đáng này.

Keywords:
employee (n): nhân viên, month (n): tháng, teamwork (n): tinh thần đồng đội, dedication (n): sự tận tâm, asset (n): tài sản, recognition (n): sự công nhận', 20, 5);
