INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Product Security Breach: A Major Concern' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B2', 'Chúng tôi đang làm việc với cơ quan nào để điều tra sự cố bảo mật?', 'Cơ quan chức năng', 'Cơ quan bảo mật', 'Cơ quan hỗ trợ khách hàng', 'Cơ quan cập nhật thông tin', 'A', 'A', 'Chúng tôi đang làm việc với cơ quan chức năng để điều tra sự cố bảo mật');
