INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Update to Employee Code of Conduct: AI Usage', 'B2', 'Dear employees, as we continue to integrate artificial intelligence (AI) into our daily operations, it is essential that we establish clear guidelines for its use. The purpose of this update to our Employee Code of Conduct is to provide a framework for responsible AI usage and to ensure that we maintain the highest standards of integrity and professionalism in our work. The updated code of conduct includes the following key points: AI systems must be used in accordance with their intended purpose and must not be used for personal gain or to compromise company data. Employees are expected to report any instances of AI misuse or suspected security breaches to their supervisor or the IT department immediately. Failure to comply with this code of conduct may result in disciplinary action, up to and including termination of employment. We appreciate your cooperation and commitment to upholding our company''s values and standards. If you have any questions or concerns, please do not hesitate to reach out to your supervisor or HR representative.', 'Vietnamese Translation:
Kính gửi các nhân viên, trong khi chúng ta tiếp tục tích hợp trí tuệ nhân tạo (AI) vào các hoạt động hàng ngày, thì việc thiết lập các quy định rõ ràng về việc sử dụng AI là rất quan trọng. Mục đích của bản cập nhật này về Quy tắc Hành vi của Nhân viên là cung cấp một khung khổ cho việc sử dụng AI một cách có trách nhiệm và đảm bảo rằng chúng ta duy trì những tiêu chuẩn cao nhất về sự trung thực và chuyên nghiệp trong công việc. Bản cập nhật quy tắc hành vi bao gồm các điểm chính sau: Các hệ thống AI phải được sử dụng theo mục đích đã định và không được sử dụng để kiếm lợi cá nhân hoặc để làm suy yếu dữ liệu công ty. Nhân viên được yêu cầu báo cáo bất kỳ trường hợp nào về việc lạm dụng AI hoặc nghi ngờ về các cuộc tấn công bảo mật đến người quản lý hoặc bộ phận IT ngay lập tức. Việc không tuân thủ quy tắc hành vi này có thể dẫn đến các biện pháp kỷ luật, bao gồm cả việc sa thải. Chúng tôi đánh giá cao sự hợp tác và cam kết của bạn trong việc duy trì các giá trị và tiêu chuẩn của công ty. Nếu bạn có bất kỳ câu hỏi hoặc mối quan ngại nào, xin vui lòng liên hệ với người quản lý hoặc đại diện nhân sự của bạn.

Keywords:
AI (n): trí tuệ nhân tạo, code of conduct (n): quy tắc hành vi, misuse (v): lạm dụng, security breach (n): cuộc tấn công bảo mật, termination (n): sa thải, supervisor (n): người quản lý, HR (n): bộ phận nhân sự', 20, 3);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Update to Employee Code of Conduct: AI Usage' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'B2', 'Mục đích của bản cập nhật này về Quy tắc Hành vi của Nhân viên là gì?', 'Để thiết lập các quy định rõ ràng về việc sử dụng AI', 'Để cung cấp một khung khổ cho việc sử dụng AI một cách có trách nhiệm', 'Để đảm bảo rằng nhân viên tuân thủ các quy định về bảo mật', 'Để tăng cường kỷ luật trong công ty', 'B', 'B', 'Bản cập nhật này về Quy tắc Hành vi của Nhân viên được thiết kế để cung cấp một khung khổ cho việc sử dụng AI một cách có trách nhiệm và đảm bảo rằng nhân viên tuân thủ các quy định về bảo mật.');
