INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Creating a Culture of Psychological Safety' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B2', 'Tại sao các nhà lãnh đạo nên mô hình hóa hành vi mà họ muốn thấy ở các thành viên nhóm?', 'Bởi vì họ muốn tạo ra một nền văn hóa an toàn tâm lý', 'Bởi vì họ muốn khuyến khích sáng tạo và hợp tác', 'Bởi vì họ muốn tạo ra một môi trường làm việc tích cực', 'Bởi vì họ muốn tạo ra một nền văn hóa minh bạch', 'C', 'C', 'Các nhà lãnh đạo nên mô hình hóa hành vi mà họ muốn thấy ở các thành viên nhóm để tạo ra một môi trường làm việc tích cực.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Creating a Culture of Psychological Safety' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'B2', 'Các chiến lược nào để các nhà lãnh đạo tạo ra một nền văn hóa an toàn tâm lý?', 'Foster open communication, practice active listening, be approachable and transparent, celebrate failures, lead by example', 'Foster open communication, practice active listening, be approachable and transparent, celebrate successes, lead by example', 'Foster open communication, practice active listening, be approachable and transparent, punish failures, lead by example', 'Foster open communication, practice active listening, be approachable and transparent, celebrate failures, punish failures', 'A', 'A', 'Các chiến lược để các nhà lãnh đạo tạo ra một nền văn hóa an toàn tâm lý bao gồm khuyến khích giao tiếp mở, thực hành lắng nghe tích cực, tiếp cận và minh bạch, chúc mừng thất bại và lãnh đạo bằng ví dụ.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Annual Corporate Social Responsibility (CSR) Report', 'B2', 'Our company is committed to making a positive impact on the environment and the communities we serve. As part of our corporate social responsibility (CSR) efforts, we have implemented various initiatives to reduce our carbon footprint and promote sustainability. In our annual CSR report, we highlight our achievements and progress towards our goals. This year, we have achieved a 25% reduction in energy consumption and a 30% reduction in waste production. We have also implemented a new recycling program and partnered with local organizations to support community development projects. Our CSR report provides a detailed account of our activities and the impact we have made. We believe that our CSR efforts are essential to creating a better future for our stakeholders and the environment.', 'Vietnamese Translation:
Chúng tôi cam kết tạo ra tác động tích cực đến môi trường và cộng đồng mà chúng tôi phục vụ.  Là một phần của nỗ lực trách nhiệm xã hội doanh nghiệp (CSR), chúng tôi đã thực hiện các sáng kiến khác nhau để giảm thiểu carbon và thúc đẩy sự bền vững.  Trong báo cáo CSR hàng năm của chúng tôi, chúng tôi nhấn mạnh thành tựu và tiến bộ của chúng tôi hướng đến mục tiêu.  Năm nay, chúng tôi đã đạt được 25% giảm tiêu thụ năng lượng và 30% giảm sản xuất rác thải.  Chúng tôi cũng đã thực hiện chương trình tái chế mới và hợp tác với các tổ chức địa phương để hỗ trợ các dự án phát triển cộng đồng.  Báo cáo CSR của chúng tôi cung cấp thông tin chi tiết về các hoạt động và tác động của chúng tôi.  Chúng tôi tin rằng nỗ lực CSR của chúng tôi là cần thiết để tạo ra một tương lai tốt đẹp hơn cho các bên liên quan và môi trường.

Keywords:
corporate social responsibility (CSR): trách nhiệm xã hội doanh nghiệp, carbon footprint: dấu ấn carbon, sustainability: sự bền vững, recycling: tái chế, community development: phát triển cộng đồng', 20, 5);
