INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Audit Report Findings and Remediation Actions' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'B2', 'Công ty đã thuê một giám đốc tài chính mới để thực hiện chức vụ nào?', 'Giám đốc tài chính', 'Giám đốc kiểm toán', 'Giám đốc tài chính và kiểm toán', 'Giám đốc tài chính và giám sát việc thực hiện hệ thống mới', 'D', 'D', 'Công ty đã thuê một giám đốc tài chính mới để giám sát việc thực hiện hệ thống mới và đảm bảo rằng hồ sơ tài chính của công ty là chính xác và đáng tin cậy.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Audit Report Findings and Remediation Actions' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'B2', 'Hệ thống kiểm soát nội bộ mới của công ty sẽ được thực hiện đầy đủ trong bao lâu?', 'Ba tháng', 'Hai tháng', 'Sáu tháng', 'Một năm', 'C', 'C', 'Hệ thống kiểm soát nội bộ mới của công ty được dự kiến sẽ được thực hiện đầy đủ trong sáu tháng tới.');
