INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Shift to a Service-Based Economy' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'What is an example of a new value proposition in the education sector?', 'Traditional teaching methods', 'Experiential learning approaches, including hands-on training and project-based learning', 'Online courses that cater to different learning styles', 'A combination of all the above', 'D', 'D', 'Các tổ chức giáo dục đang chuyển khỏi các phương pháp giảng dạy truyền thống và hướng tới các phương pháp học tập trải nghiệm hơn.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Shift to a Service-Based Economy' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'What is the overall impact of the shift to a service-based economy?', 'It will lead to a decline in the quality of life for people around the world', 'It will create new opportunities for growth and improvement in the quality of life', 'It will have no impact on the quality of life', 'It will lead to a shift in the global economy', 'B', 'B', 'Sự chuyển đổi sang một nền kinh tế dựa trên dịch vụ là một cơ hội để tạo ra các đề xuất giá trị mới, thúc đẩy tăng trưởng và cải thiện chất lượng cuộc sống cho người dân trên toàn thế giới.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'The Supreme Court Ruling on Corporate Liability', 'C1', 'In a landmark decision, the Supreme Court has ruled that corporations can be held liable for human rights abuses committed by their subsidiaries. The court''s majority opinion, written by Justice Smith, states that corporations have a duty to ensure that their subsidiaries comply with international human rights standards. This ruling has significant implications for multinational corporations operating in countries with poor human rights records. The court''s decision was met with praise from human rights groups, who argue that it will help to hold corporations accountable for their actions. However, some critics argue that the ruling goes too far, and that it will stifle economic growth by imposing unnecessary regulatory burdens on businesses. The court''s ruling is also seen as a victory for the victims of human rights abuses, who will now have a clearer path to seeking justice. As one human rights activist noted, ''This ruling is a major step forward for human rights, and it sends a powerful message to corporations that they cannot ignore their responsibilities.''', 'Vietnamese Translation:
Trong một quyết định lịch sử, Tòa án Tối cao đã quyết định rằng các công ty có thể bị truy cứu trách nhiệm hình sự về các tội ác nhân quyền do các chi nhánh của họ thực hiện.  Đa số ý kiến của tòa án, được viết bởi Chánh án Smith, tuyên bố rằng các công ty có nghĩa vụ đảm bảo rằng các chi nhánh của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế.  Quyết định này có ý nghĩa quan trọng đối với các công ty đa quốc gia hoạt động ở các quốc gia có hồ sơ nhân quyền kém.  Quyết định của tòa án đã nhận được sự khen ngợi từ các tổ chức nhân quyền, họ cho rằng nó sẽ giúp các công ty được truy cứu trách nhiệm về hành động của họ.  Tuy nhiên, một số người chỉ trích cho rằng quyết định này đi quá xa và rằng nó sẽ làm chậm sự phát triển kinh tế bằng cách đặt các yêu cầu quản lý không cần thiết lên các doanh nghiệp.  Quyết định của tòa án cũng được coi là một chiến thắng cho nạn nhân của các tội ác nhân quyền, họ sẽ có một con đường rõ ràng hơn để tìm kiếm công lý.  Như một nhà hoạt động nhân quyền đã nhận xét, ''Quyết định này là một bước tiến lớn về nhân quyền và nó gửi một thông điệp mạnh mẽ cho các công ty rằng họ không thể bỏ qua trách nhiệm của mình.''

Keywords:
corporate liability (n): trách nhiệm hình sự của các công ty, subsidiary (n): chi nhánh, human rights (n): nhân quyền, multinational corporation (n): công ty đa quốc gia, regulatory burden (n): gánh nặng quản lý, economic growth (n): sự phát triển kinh tế', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Supreme Court Ruling on Corporate Liability' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'Theo quyết định của Tòa án Tối cao, các công ty có thể bị truy cứu trách nhiệm hình sự về các tội ác nhân quyền được thực hiện bởi:', 'Các chi nhánh của họ', 'Các đối tác kinh doanh của họ', 'Các nhân viên của họ', 'Các khách hàng của họ', 'A', 'A', 'Theo quyết định của Tòa án Tối cao, các công ty có thể bị truy cứu trách nhiệm hình sự về các tội ác nhân quyền được thực hiện bởi các chi nhánh của họ.');
