INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Supreme Court Ruling on Corporate Liability' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'Theo quyết định của Tòa án Tối cao, các công ty có nghĩa vụ:', 'Đảm bảo rằng các chi nhánh của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế', 'Đảm bảo rằng các đối tác kinh doanh của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế', 'Đảm bảo rằng các nhân viên của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế', 'Đảm bảo rằng các khách hàng của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế', 'A', 'A', 'Theo quyết định của Tòa án Tối cao, các công ty có nghĩa vụ đảm bảo rằng các chi nhánh của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế.');
