INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Supreme Court Ruling on Corporate Liability' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Theo quyết định của Tòa án Tối cao, các nạn nhân của các tội ác nhân quyền có thể:', 'Tìm kiếm công lý một cách rõ ràng hơn', 'Tìm kiếm công lý một cách khó khăn hơn', 'Không tìm kiếm công lý', 'Tìm kiếm công lý một cách không rõ ràng', 'A', 'A', 'Theo quyết định của Tòa án Tối cao, các nạn nhân của các tội ác nhân quyền có thể tìm kiếm công lý một cách rõ ràng hơn.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Comprehensive Meta-Analysis Summary', 'C1', 'A recent meta-analysis published in the Journal of Clinical Epidemiology has provided a comprehensive summary of the effects of exercise on cardiovascular disease. The study, which pooled data from 17 randomized controlled trials, found that regular exercise significantly reduces the risk of cardiovascular disease in both men and women. The analysis also revealed that the benefits of exercise on cardiovascular health are dose-dependent, with greater reductions in risk observed with higher levels of physical activity. Furthermore, the study found that exercise has a positive impact on mental health, with regular physical activity associated with lower levels of anxiety and depression. The findings of this meta-analysis have important implications for public health policy and practice, highlighting the need for increased investment in physical activity programs and infrastructure. As the World Health Organization has noted, physical inactivity is a major risk factor for non-communicable diseases, and increasing physical activity levels is a key strategy for reducing the burden of these diseases.', 'Vietnamese Translation:
Tóm tắt tổng quan của một phân tích tổng hợp gần đây được xuất bản trên Journal of Clinical Epidemiology đã cung cấp một tóm tắt toàn diện về tác động của tập thể dục lên bệnh tim mạch. Nghiên cứu, đã tổng hợp dữ liệu từ 17 thử nghiệm lâm sàng ngẫu nhiên, đã tìm thấy rằng tập thể dục đều đặn giảm đáng kể nguy cơ bệnh tim mạch ở cả nam và nữ. Phân tích cũng tiết lộ rằng lợi ích của tập thể dục đối với sức khỏe tim mạch phụ thuộc vào liều lượng, với những giảm nguy cơ lớn hơn được quan sát thấy với mức độ tập thể dục cao hơn. Nghiên cứu cũng tìm thấy rằng tập thể dục có tác động tích cực đối với sức khỏe tâm thần, với tập thể dục đều đặn liên quan đến mức độ lo lắng và trầm cảm thấp hơn. Kết quả của phân tích tổng hợp này có tầm quan trọng đối với chính sách và thực hành sức khỏe công cộng, nhấn mạnh nhu cầu đầu tư tăng cường vào các chương trình và cơ sở vật chất tập thể dục. Như Tổ chức Y tế Thế giới đã lưu ý, thiếu hoạt động thể chất là một yếu tố nguy cơ lớn đối với các bệnh không lây truyền, và tăng cường hoạt động thể chất là một chiến lược quan trọng để giảm bớt gánh nặng của các bệnh này.

Keywords:
exercise (v): tập thể dục, cardiovascular disease (n): bệnh tim mạch, meta-analysis (n): phân tích tổng hợp, randomized controlled trial (n): thử nghiệm lâm sàng ngẫu nhiên, dose-dependent (adj): phụ thuộc vào liều lượng, anxiety (n): lo lắng, depression (n): trầm cảm', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Meta-Analysis Summary' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'What type of study was conducted to investigate the effects of exercise on cardiovascular disease?', 'A survey', 'A meta-analysis', 'A randomized controlled trial', 'A case study', 'B', 'B', 'Phân tích tổng hợp là một phương pháp nghiên cứu tổng hợp dữ liệu từ nhiều nghiên cứu khác nhau để tìm kiếm kết quả tổng thể.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Meta-Analysis Summary' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'What was the main finding of the meta-analysis regarding the relationship between exercise and cardiovascular disease?', 'Exercise has no effect on cardiovascular disease', 'Exercise increases the risk of cardiovascular disease', 'Exercise reduces the risk of cardiovascular disease', 'Exercise has no impact on cardiovascular health', 'C', 'C', 'Phân tích tổng hợp đã tìm thấy rằng tập thể dục đều đặn giảm đáng kể nguy cơ bệnh tim mạch.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Meta-Analysis Summary' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'What is the relationship between exercise and mental health according to the meta-analysis?', 'Exercise has a negative impact on mental health', 'Exercise has no impact on mental health', 'Exercise has a positive impact on mental health', 'Exercise increases anxiety and depression', 'C', 'C', 'Phân tích tổng hợp đã tìm thấy rằng tập thể dục đều đặn liên quan đến mức độ lo lắng và trầm cảm thấp hơn.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Meta-Analysis Summary' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'What is the implication of the meta-analysis for public health policy and practice?', 'Increased investment in physical activity programs and infrastructure is not necessary', 'Physical activity programs and infrastructure should be reduced', 'Increased investment in physical activity programs and infrastructure is necessary', 'Physical activity has no impact on public health', 'C', 'C', 'Phân tích tổng hợp đã nhấn mạnh nhu cầu đầu tư tăng cường vào các chương trình và cơ sở vật chất tập thể dục.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Meta-Analysis Summary' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'What is the World Health Organization''s stance on physical inactivity?', 'Physical inactivity is not a major risk factor for non-communicable diseases', 'Physical inactivity is a minor risk factor for non-communicable diseases', 'Physical inactivity is a major risk factor for non-communicable diseases', 'Physical inactivity has no impact on public health', 'C', 'C', 'Tổ chức Y tế Thế giới đã lưu ý rằng thiếu hoạt động thể chất là một yếu tố nguy cơ lớn đối với các bệnh không lây truyền.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'The Ethics of Modern Technology', 'C1', 'The advent of modern technology has brought about unprecedented changes in the way we live and interact with one another. On one hand, it has enabled us to communicate with people across the globe in real-time, access vast amounts of information, and automate many mundane tasks. However, it has also raised important questions about the ethics of our actions in the digital age.

One of the most pressing concerns is the issue of privacy. With the rise of social media, people are sharing more personal information than ever before, often without realizing the potential consequences. This has led to a culture of voyeurism, where individuals feel entitled to snoop into others'' private lives. Furthermore, the use of algorithms to target advertising and manipulate public opinion has created a sense of unease, as people begin to question the authenticity of the information they consume.

Another issue that has gained significant attention is the impact of technology on our mental health. The constant stream of notifications, the pressure to present a perfect online image, and the fear of missing out (FOMO) have all contributed to a sense of anxiety and stress. Moreover, the blurring of boundaries between work and personal life has led to burnout and decreased productivity.

In light of these concerns, it is essential to re-examine our values and priorities. We must recognize that technology is a tool, not an end in itself, and that our actions have consequences. By being more mindful of our online behavior, we can create a more compassionate and responsible digital community.

Ultimately, the ethics of modern technology is a complex and multifaceted issue that requires a nuanced approach. It demands that we engage in critical thinking, empathy, and self-reflection. By doing so, we can harness the benefits of technology while minimizing its negative effects and creating a better world for all.', 'Vietnamese Translation:
Sự xuất hiện của công nghệ hiện đại đã mang lại những thay đổi chưa từng có về cách chúng ta sống và tương tác với nhau. Một bên, nó đã cho phép chúng ta giao tiếp với người khác trên toàn cầu trong thời gian thực, truy cập vào lượng thông tin khổng lồ và tự động hóa nhiều công việc nhàm chán. Tuy nhiên, nó cũng đã đặt ra những câu hỏi quan trọng về đạo đức của hành động của chúng ta trong thời đại số.

Một trong những mối quan tâm cấp thiết nhất là vấn đề bảo mật. Với sự phát triển của mạng xã hội, người ta đang chia sẻ thông tin cá nhân nhiều hơn bao giờ hết, thường không nhận ra những hậu quả tiềm ẩn. Điều này đã dẫn đến một nền văn hóa của sự quan sát, nơi các cá nhân cảm thấy có quyền được nhìn vào cuộc sống riêng tư của người khác. Ngoài ra, việc sử dụng các thuật toán để nhắm mục tiêu quảng cáo và thao túng ý kiến công chúng đã tạo ra một cảm giác không chắc chắn, khi người ta bắt đầu đặt câu hỏi về tính xác thực của thông tin họ tiêu thụ.

Một vấn đề khác đã thu hút sự chú ý đáng kể là tác động của công nghệ đối với sức khỏe tâm thần của chúng ta. Dòng chảy liên tục của thông báo, áp lực phải thể hiện hình ảnh trực tuyến hoàn hảo và sợ bỏ lỡ (FOMO) đã góp phần vào cảm giác lo lắng và căng thẳng. Hơn nữa, sự nhầm lẫn ranh giới giữa công việc và cuộc sống cá nhân đã dẫn đến cháy công việc và giảm năng suất.

Trước những mối quan tâm này, điều cần thiết là phải tái đánh giá giá trị và ưu tiên của chúng ta. Chúng ta phải nhận ra rằng công nghệ là một công cụ, không phải là một mục đích cuối cùng, và rằng hành động của chúng ta có hậu quả. Bằng cách trở nên tự giác hơn về hành vi trực tuyến của mình, chúng ta có thể tạo ra một cộng đồng số cảm thông và có trách nhiệm hơn.

Cuối cùng, đạo đức của công nghệ hiện đại là một vấn đề phức tạp và đa chiều đòi hỏi một cách tiếp cận tinh tế. Nó đòi hỏi chúng ta phải tham gia vào suy nghĩ logic, lòng trắc ẩn và tự phản ánh. Bằng cách làm như vậy, chúng ta có thể khai thác lợi ích của công nghệ trong khi giảm thiểu tác động tiêu cực và tạo ra một thế giới tốt đẹp hơn cho tất cả mọi người.

Keywords:
technology (n): công nghệ, ethics (n): đạo đức, privacy (n): bảo mật, mental health (n): sức khỏe tâm thần, responsibility (n): trách nhiệm, authenticity (n): tính xác thực, compassion (n): lòng trắc ẩn', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Ethics of Modern Technology' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'What is the main concern of the author regarding modern technology?', 'The benefits of technology outweigh its negative effects.', 'The issue of privacy is a pressing concern.', 'The impact of technology on our mental health is negligible.', 'The use of technology has no impact on our lives.', 'B', 'B', 'Tác giả quan tâm chính của tác giả về công nghệ hiện đại là vấn đề bảo mật.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Ethics of Modern Technology' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'What has led to a culture of voyeurism?', 'The rise of social media.', 'The use of algorithms to target advertising.', 'The blurring of boundaries between work and personal life.', 'The fear of missing out (FOMO).', 'A', 'A', 'Sự phát triển của mạng xã hội đã dẫn đến một nền văn hóa của sự quan sát.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Ethics of Modern Technology' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'What is the impact of technology on our mental health?', 'It has a positive impact.', 'It has a negligible impact.', 'It leads to anxiety and stress.', 'It has no impact.', 'C', 'C', 'Công nghệ đã dẫn đến lo lắng và căng thẳng.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Ethics of Modern Technology' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'What is the author''s recommendation for creating a more responsible digital community?', 'We should ignore the negative effects of technology.', 'We should be more mindful of our online behavior.', 'We should rely solely on technology for our needs.', 'We should abandon technology altogether.', 'B', 'B', 'Tác giả khuyên chúng ta nên trở nên tự giác hơn về hành vi trực tuyến của mình.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Ethics of Modern Technology' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'What is the ultimate goal of the author?', 'To promote the use of technology.', 'To raise awareness about the ethics of technology.', 'To create a better world for all.', 'To eliminate the negative effects of technology.', 'C', 'C', 'Mục tiêu cuối cùng của tác giả là tạo ra một thế giới tốt đẹp hơn cho tất cả mọi người.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Comprehensive Grant Proposal', 'C1', 'The proposed project, titled ''Sustainable Energy for Rural Communities,'' aims to provide renewable energy solutions to remote villages in developing countries. Our team has conducted extensive research on the current energy landscape and identified a significant gap in access to reliable and sustainable energy sources. This project seeks to address this issue by implementing a comprehensive energy system that includes solar panels, wind turbines, and energy storage units. The proposed system will not only provide a reliable source of energy but also create jobs and stimulate local economies. We plan to partner with local organizations and community leaders to ensure the project''s success and sustainability. The project''s budget is estimated at $1 million, which will be used to cover the costs of equipment, installation, and training. We believe that this project has the potential to make a significant impact on the lives of thousands of people and contribute to a more sustainable future.', 'Vietnamese Translation:
Đề xuất dự án chi tiết, có tựa đề ''Năng lượng bền vững cho cộng đồng nông thôn,'' nhằm mục đích cung cấp các giải pháp năng lượng tái tạo cho các làng mạc cách xa ở các nước đang phát triển. Đội ngũ của chúng tôi đã thực hiện nghiên cứu rộng rãi về hiện trạng năng lượng và xác định được khoảng trống đáng kể trong việc truy cập vào nguồn năng lượng đáng tin cậy và bền vững. Dự án này nhằm giải quyết vấn đề này bằng cách thực hiện hệ thống năng lượng toàn diện bao gồm các tấm pin năng lượng mặt trời, tua-bin gió và các đơn vị lưu trữ năng lượng. Hệ thống đề xuất sẽ không chỉ cung cấp nguồn năng lượng đáng tin cậy mà còn tạo việc làm và kích thích các nền kinh tế địa phương. Chúng tôi dự định hợp tác với các tổ chức và lãnh đạo cộng đồng địa phương để đảm bảo thành công và bền vững của dự án. Ngân sách dự án được ước tính là 1 triệu đô la, sẽ được sử dụng để chi trả cho chi phí thiết bị, lắp đặt và đào tạo. Chúng tôi tin rằng dự án này có tiềm năng tạo ra tác động đáng kể trên cuộc sống của hàng nghìn người và đóng góp vào một tương lai bền vững hơn.

Keywords:
renewable energy (n): năng lượng tái tạo, sustainable (adj): bền vững, comprehensive (adj): toàn diện, solar panels (n): các tấm pin năng lượng mặt trời, wind turbines (n): tua-bin gió, energy storage (n): lưu trữ năng lượng, budget (n): ngân sách, impact (n): tác động', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Grant Proposal' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'Mục tiêu chính của dự án này là gì?', 'Cung cấp năng lượng tái tạo cho các làng mạc cách xa', 'Tạo việc làm và kích thích các nền kinh tế địa phương', 'Đảm bảo thành công và bền vững của dự án', 'Cung cấp nguồn năng lượng đáng tin cậy cho các làng mạc cách xa', 'D', 'D', 'Dự án này nhằm cung cấp nguồn năng lượng đáng tin cậy cho các làng mạc cách xa và tạo việc làm, kích thích các nền kinh tế địa phương.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Grant Proposal' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'Ngân sách dự án được ước tính là bao nhiêu?', '500.000 đô la', '1 triệu đô la', '2 triệu đô la', '3 triệu đô la', 'B', 'B', 'Ngân sách dự án được ước tính là 1 triệu đô la.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Grant Proposal' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'Dự án này sẽ được thực hiện như thế nào?', 'Chỉ sử dụng các tấm pin năng lượng mặt trời', 'Chỉ sử dụng tua-bin gió', 'Sử dụng cả các tấm pin năng lượng mặt trời và tua-bin gió', 'Không sử dụng các tấm pin năng lượng mặt trời và tua-bin gió', 'C', 'C', 'Dự án này sẽ được thực hiện bằng cách sử dụng cả các tấm pin năng lượng mặt trời và tua-bin gió.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Grant Proposal' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'Dự án này sẽ tạo ra tác động gì?', 'Tác động tiêu cực đến môi trường', 'Tác động tích cực đến môi trường', 'Không tạo ra tác động nào', 'Tác động tiêu cực đến kinh tế', 'B', 'B', 'Dự án này sẽ tạo ra tác động tích cực đến môi trường.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Comprehensive Grant Proposal' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Dự án này sẽ được thực hiện ở đâu?', 'Các làng mạc cách xa ở các nước đang phát triển', 'Các thành phố lớn ở các nước phát triển', 'Các khu vực nông thôn ở các nước đang phát triển', 'Các khu vực đô thị ở các nước phát triển', 'A', 'A', 'Dự án này sẽ được thực hiện ở các làng mạc cách xa ở các nước đang phát triển.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Critical Analysis of James Joyce''s Ulysses', 'C1', 'James Joyce''s Ulysses is a novel that has been the subject of much debate and analysis since its publication in 1922. On the surface, the novel appears to be a simple tale of a man''s journey through Dublin, but upon closer inspection, it reveals itself to be a complex and multifaceted work of literature. One of the key themes of the novel is the concept of identity, and how it is shaped by our experiences and interactions with the world around us. Through the character of Leopold Bloom, Joyce explores the idea that identity is not fixed, but rather is constantly evolving and changing. This is reflected in the novel''s use of stream-of-consciousness narration, which allows the reader to experience the world through Bloom''s eyes and gain a deeper understanding of his thoughts and feelings. Another key theme of the novel is the concept of nationality and how it is tied to identity. Through Bloom''s experiences as a Jewish man living in Ireland, Joyce highlights the tensions and conflicts that can arise between different cultural and national identities. Overall, Ulysses is a novel that challenges the reader to think critically about the nature of identity and how it is shaped by our experiences and interactions with the world around us.', 'Vietnamese Translation:
Ulysses của James Joyce là một tiểu thuyết đã trở thành chủ đề của nhiều cuộc tranh luận và phân tích kể từ khi xuất bản vào năm 1922. Trên bề mặt, tiểu thuyết này dường như là một câu chuyện đơn giản về một người đàn ông đi qua Dublin, nhưng khi xem xét kỹ lưỡng, nó tiết lộ bản thân là một tác phẩm văn học phức tạp và đa dạng. Một trong những chủ đề chính của tiểu thuyết này là khái niệm về bản sắc, và cách nó được hình thành bởi những trải nghiệm và tương tác của chúng ta với thế giới xung quanh. Thông qua nhân vật Leopold Bloom, Joyce khám phá ý tưởng rằng bản sắc không phải là cố định, mà thay vào đó là luôn biến đổi và thay đổi. Điều này được phản ánh trong việc sử dụng thể loại kể chuyện dòng ý thức trong tiểu thuyết, cho phép người đọc trải nghiệm thế giới thông qua mắt của Bloom và có được một hiểu biết sâu sắc hơn về suy nghĩ và cảm xúc của ông. Chủ đề khác của tiểu thuyết này là khái niệm về quốc tịch và cách nó liên quan đến bản sắc. Thông qua những trải nghiệm của Bloom như một người Do Thái sống ở Ireland, Joyce làm nổi bật những căng thẳng và xung đột có thể xảy ra giữa các bản sắc văn hóa và quốc gia khác nhau. Tóm lại, Ulysses là một tiểu thuyết thách thức người đọc phải suy nghĩ một cách nghiêm túc về bản chất của bản sắc và cách nó được hình thành bởi những trải nghiệm và tương tác của chúng ta với thế giới xung quanh.

Keywords:
identity (n): bản sắc, nationality (n): quốc tịch, stream-of-consciousness (n): dòng ý thức, narration (n): kể chuyện, character (n): nhân vật, theme (n): chủ đề, literature (n): văn học', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Analysis of James Joyce''s Ulysses' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'What is the main theme of James Joyce''s Ulysses?', 'The struggle for independence in Ireland', 'The concept of identity and how it is shaped by our experiences and interactions with the world around us', 'The importance of nationality and how it is tied to identity', 'The role of literature in shaping our understanding of the world', 'B', 'B', 'Chủ đề chính của tiểu thuyết Ulysses của James Joyce là khái niệm về bản sắc và cách nó được hình thành bởi những trải nghiệm và tương tác của chúng ta với thế giới xung quanh.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Analysis of James Joyce''s Ulysses' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'How does the novel''s use of stream-of-consciousness narration contribute to the reader''s understanding of the character of Leopold Bloom?', 'It allows the reader to experience the world through Bloom''s eyes, gaining a deeper understanding of his thoughts and feelings', 'It provides a detailed description of Bloom''s physical appearance', 'It offers a critical analysis of Bloom''s actions and decisions', 'It ignores Bloom''s thoughts and feelings altogether', 'A', 'A', 'Sử dụng thể loại kể chuyện dòng ý thức trong tiểu thuyết cho phép người đọc trải nghiệm thế giới thông qua mắt của Bloom và có được một hiểu biết sâu sắc hơn về suy nghĩ và cảm xúc của ông.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Analysis of James Joyce''s Ulysses' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'What is the significance of the character of Leopold Bloom in the novel?', 'He represents the struggle for independence in Ireland', 'He embodies the concept of identity and how it is shaped by our experiences and interactions with the world around us', 'He symbolizes the importance of nationality and how it is tied to identity', 'He is a minor character with no significant role in the novel', 'B', 'B', 'Nhân vật Leopold Bloom đại diện cho khái niệm về bản sắc và cách nó được hình thành bởi những trải nghiệm và tương tác của chúng ta với thế giới xung quanh.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Analysis of James Joyce''s Ulysses' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'What is the author''s purpose in exploring the theme of nationality in the novel?', 'To highlight the importance of nationality in shaping our identity', 'To demonstrate the tensions and conflicts that can arise between different cultural and national identities', 'To provide a detailed description of the Irish landscape', 'To ignore the theme of nationality altogether', 'B', 'B', 'Tác giả khám phá chủ đề quốc tịch trong tiểu thuyết để làm nổi bật những căng thẳng và xung đột có thể xảy ra giữa các bản sắc văn hóa và quốc gia khác nhau.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Analysis of James Joyce''s Ulysses' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'What is the significance of the novel''s use of stream-of-consciousness narration in relation to the theme of identity?', 'It allows the reader to experience the world through the eyes of a single character, highlighting the complexities of identity', 'It provides a detailed description of the physical appearance of the characters, reinforcing the idea that identity is fixed', 'It ignores the theme of identity altogether, focusing instead on other aspects of the novel', 'It offers a critical analysis of the characters'' actions and decisions, demonstrating the importance of identity in shaping our understanding of the world', 'A', 'A', 'Sử dụng thể loại kể chuyện dòng ý thức trong tiểu thuyết cho phép người đọc trải nghiệm thế giới thông qua mắt của một nhân vật duy nhất, làm nổi bật sự phức tạp của bản sắc.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Sophisticated Marketing Strategy Report', 'C1', 'The marketing team at XYZ Corporation has been tasked with developing a comprehensive marketing strategy to promote the company''s new product line. After conducting extensive market research, the team has identified several key demographics that are likely to be interested in the product. These demographics include individuals aged 25-45, with a high level of education and a medium to high income. The team has also identified several key marketing channels that will be used to reach these demographics, including social media, email marketing, and targeted online advertising. In addition, the team has developed a content marketing strategy that will include creating high-quality blog posts, videos, and infographics that will be shared on the company''s website and social media channels. The team has also established a public relations strategy that will include reaching out to key media outlets and influencers in the industry to generate buzz and excitement around the product. Finally, the team has developed a budget and timeline for the marketing campaign, which includes a total budget of $1 million and a timeline of 6 months. The team is confident that this comprehensive marketing strategy will be successful in promoting the company''s new product line and driving sales.', 'Vietnamese Translation:
Đội ngũ tiếp thị tại XYZ Corporation đã được giao nhiệm vụ phát triển một chiến lược tiếp thị toàn diện để quảng cáo dòng sản phẩm mới của công ty. Sau khi thực hiện nghiên cứu thị trường rộng rãi, đội ngũ đã xác định được một số dân tộc quan trọng có khả năng quan tâm đến sản phẩm. Những dân tộc này bao gồm những người từ 25-45 tuổi, có trình độ học vấn cao và thu nhập trung bình đến cao. Đội ngũ cũng đã xác định được một số kênh tiếp thị quan trọng sẽ được sử dụng để tiếp cận những dân tộc này, bao gồm mạng xã hội, tiếp thị email và quảng cáo trực tuyến nhắm mục tiêu. Ngoài ra, đội ngũ đã phát triển một chiến lược tiếp thị nội dung bao gồm tạo ra các bài đăng chất lượng cao, video và infographic sẽ được chia sẻ trên trang web và các kênh mạng xã hội của công ty. Đội ngũ cũng đã thiết lập một chiến lược quan hệ công chúng bao gồm liên hệ với các phương tiện truyền thông và người ảnh hưởng trong ngành để tạo ra tiếng vang và sự phấn khích xung quanh sản phẩm. Cuối cùng, đội ngũ đã phát triển một ngân sách và lịch trình cho chiến dịch tiếp thị, bao gồm ngân sách tổng cộng 1 triệu đô la và lịch trình 6 tháng. Đội ngũ tin rằng chiến lược tiếp thị toàn diện này sẽ thành công trong việc quảng cáo dòng sản phẩm mới của công ty và tăng doanh số.

Keywords:
marketing strategy (n): chiến lược tiếp thị, demographics (n): dân tộc, social media (n): mạng xã hội, email marketing (n): tiếp thị email, content marketing (n): tiếp thị nội dung, public relations (n): quan hệ công chúng, budget (n): ngân sách', 20, 5);
