INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Critique of Sustainable Development Policies', 'C1', 'The concept of sustainable development has been widely accepted as a guiding principle for economic growth and environmental protection. However, a closer examination of the policies implemented in the name of sustainable development reveals a more complex and nuanced reality. On one hand, these policies have led to significant reductions in greenhouse gas emissions and the preservation of natural habitats. On the other hand, they have also resulted in the displacement of local communities and the concentration of economic power in the hands of a few large corporations. Furthermore, the emphasis on economic growth has led to the exploitation of natural resources, undermining the very principles of sustainability. In order to truly achieve sustainable development, it is essential to rethink our current policies and prioritize the needs of local communities and the environment over economic interests. This requires a fundamental shift in our values and a willingness to challenge the status quo. Only then can we create a more equitable and sustainable future for all.', 'Vietnamese Translation:
Khái niệm phát triển bền vững đã được chấp nhận rộng rãi như một nguyên tắc hướng dẫn cho sự tăng trưởng kinh tế và bảo vệ môi trường. Tuy nhiên, một cuộc điều tra kỹ lưỡng hơn về các chính sách được thực hiện dưới danh nghĩa phát triển bền vững cho thấy một thực tế phức tạp và đa chiều hơn. Một mặt, các chính sách này đã dẫn đến sự giảm đáng kể khí thải nhà kính và bảo tồn các khu vực tự nhiên. Mặt khác, chúng cũng đã dẫn đến việc di dời cộng đồng địa phương và tập trung quyền lực kinh tế vào tay một số ít công ty lớn. Hơn nữa, sự nhấn mạnh vào sự tăng trưởng kinh tế đã dẫn đến việc khai thác tài nguyên thiên nhiên, làm suy yếu nguyên tắc cơ bản của sự bền vững. Để đạt được thực sự phát triển bền vững, điều cần thiết là phải xem xét lại các chính sách hiện tại và ưu tiên nhu cầu của cộng đồng địa phương và môi trường hơn lợi ích kinh tế. Điều này đòi hỏi một sự thay đổi cơ bản trong giá trị của chúng ta và sự sẵn sàng thách thức hiện trạng. Chỉ khi đó, chúng ta mới có thể tạo ra một tương lai bền vững và công bằng hơn cho tất cả.

Keywords:
sustainable development (n): phát triển bền vững, greenhouse gas (n): khí thải nhà kính, natural habitat (n): môi trường tự nhiên, economic growth (n): sự tăng trưởng kinh tế, local community (n): cộng đồng địa phương, environmental protection (n): bảo vệ môi trường, economic interest (n): lợi ích kinh tế', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critique of Sustainable Development Policies' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'What is the main argument of the article?', 'Sustainable development policies are effective in reducing greenhouse gas emissions.', 'Sustainable development policies have led to the displacement of local communities and the concentration of economic power.', 'Sustainable development policies prioritize the needs of local communities and the environment over economic interests.', 'Sustainable development policies are not necessary for economic growth.', 'B', 'B', 'Bài viết chỉ ra rằng các chính sách phát triển bền vững đã dẫn đến việc di dời cộng đồng địa phương và tập trung quyền lực kinh tế vào tay một số ít công ty lớn.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critique of Sustainable Development Policies' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'What is the author''s opinion on the current policies of sustainable development?', 'The author supports the current policies and believes they are effective.', 'The author is neutral and does not have an opinion on the current policies.', 'The author believes the current policies are flawed and need to be rethought.', 'The author thinks the current policies are not necessary.', 'C', 'C', 'Tác giả cho rằng các chính sách hiện tại cần phải được xem xét lại và ưu tiên nhu cầu của cộng đồng địa phương và môi trường hơn lợi ích kinh tế.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critique of Sustainable Development Policies' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'What is the consequence of prioritizing economic growth over environmental protection?', 'The environment is protected and economic growth is increased.', 'The environment is damaged and economic growth is decreased.', 'The environment is preserved and economic growth is maintained.', 'The environment is exploited and economic growth is increased.', 'D', 'D', 'Khi ưu tiên sự tăng trưởng kinh tế hơn bảo vệ môi trường, tài nguyên thiên nhiên sẽ bị khai thác và nguyên tắc cơ bản của sự bền vững sẽ bị suy yếu.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critique of Sustainable Development Policies' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'What is the author''s suggestion for achieving sustainable development?', 'Increase economic growth and reduce environmental protection.', 'Prioritize the needs of local communities and the environment over economic interests.', 'Implement stricter regulations on businesses.', 'Invest in renewable energy sources.', 'B', 'B', 'Tác giả đề xuất rằng cần phải ưu tiên nhu cầu của cộng đồng địa phương và môi trường hơn lợi ích kinh tế để đạt được phát triển bền vững.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critique of Sustainable Development Policies' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'What is the main challenge to achieving sustainable development?', 'Lack of funding for environmental projects.', 'Resistance from local communities to environmental protection.', 'Prioritization of economic interests over environmental protection.', 'Insufficient awareness of the importance of sustainable development.', 'C', 'C', 'Bài viết chỉ ra rằng ưu tiên lợi ích kinh tế hơn bảo vệ môi trường là một thách thức chính để đạt được phát triển bền vững.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'A Critical Review of ''The Impact of Climate Change on Global Food Systems''', 'C1', 'The book ''The Impact of Climate Change on Global Food Systems'' is a comprehensive analysis of the effects of climate change on the world''s food supply. Written by a team of experts in the field, the book provides a detailed examination of the complex relationships between climate change, agriculture, and food security. The authors argue that climate change is having a devastating impact on global food systems, leading to reduced crop yields, increased food prices, and decreased access to nutritious food for vulnerable populations. They also propose a range of solutions to mitigate these effects, including the adoption of climate-resilient agricultural practices, the development of climate-tolerant crop varieties, and the implementation of policies to support small-scale farmers. While the book is well-researched and well-written, it is not without its limitations. The authors'' focus on the global North and their neglect of the experiences of small-scale farmers in the global South are notable omissions. Additionally, the book''s emphasis on technological solutions to climate change may be seen as overly simplistic. Nevertheless, ''The Impact of Climate Change on Global Food Systems'' is an important contribution to the field of climate change research and a valuable resource for policymakers, researchers, and practitioners working to address the challenges posed by climate change.', 'Vietnamese Translation:
Sách ''Ảnh hưởng của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu'' là một phân tích toàn diện về tác động của biến đổi khí hậu đối với nguồn cung thực phẩm toàn cầu. Được viết bởi một đội ngũ chuyên gia trong lĩnh vực này, sách cung cấp một phân tích chi tiết về các mối quan hệ phức tạp giữa biến đổi khí hậu, nông nghiệp và an ninh thực phẩm. Các tác giả lập luận rằng biến đổi khí hậu đang có tác động tiêu cực nghiêm trọng đối với hệ thống thực phẩm toàn cầu, dẫn đến giảm sản lượng cây trồng, tăng giá thực phẩm và giảm tiếp cận thực phẩm dinh dưỡng cho các nhóm dân số dễ bị tổn thương. Họ cũng đề xuất một loạt các giải pháp để giảm thiểu tác động này, bao gồm việc áp dụng các phương pháp nông nghiệp có khả năng chống chịu với biến đổi khí hậu, phát triển các giống cây trồng có khả năng chống chịu với khí hậu và thực hiện các chính sách để hỗ trợ các nông dân nhỏ. Mặc dù sách được nghiên cứu kỹ lưỡng và được viết tốt, nhưng nó không thể thiếu một số hạn chế. Fokus của tác giả vào khu vực Bắc bán cầu và sự bỏ qua kinh nghiệm của các nông dân nhỏ ở khu vực Nam bán cầu là những thiếu sót đáng chú ý. Ngoài ra, sự nhấn mạnh của sách vào các giải pháp công nghệ đối với biến đổi khí hậu có thể được coi là quá đơn giản. Tuy nhiên, ''Ảnh hưởng của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu'' là một đóng góp quan trọng vào lĩnh vực nghiên cứu biến đổi khí hậu và là một nguồn tài nguyên giá trị cho các chính sách gia, nghiên cứu viên và chuyên gia đang làm việc để giải quyết thách thức do biến đổi khí hậu gây ra.

Keywords:
climate change (n): biến đổi khí hậu, agriculture (n): nông nghiệp, food security (n): an ninh thực phẩm, crop yields (n): sản lượng cây trồng, climate-resilient (adj): có khả năng chống chịu với biến đổi khí hậu, climate-tolerant (adj): có khả năng chống chịu với khí hậu, small-scale farmers (n): nông dân nhỏ', 20, 5);
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Review of ''The Impact of Climate Change on Global Food Systems''' ORDER BY id DESC LIMIT 1), 1, 'MULTIPLE_CHOICE', 'C1', 'What is the main topic of the book ''The Impact of Climate Change on Global Food Systems''?', 'The effects of climate change on the world''s oceans', 'The impact of climate change on global food systems', 'The role of technology in mitigating climate change', 'The economic benefits of renewable energy', 'B', 'B', 'Sách ''Ảnh hưởng của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu'' chủ yếu tập trung vào tác động của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Review of ''The Impact of Climate Change on Global Food Systems''' ORDER BY id DESC LIMIT 1), 2, 'MULTIPLE_CHOICE', 'C1', 'What are some of the solutions proposed by the authors to mitigate the effects of climate change on global food systems?', 'Adopting climate-resilient agricultural practices and developing climate-tolerant crop varieties', 'Implementing policies to support small-scale farmers and promoting sustainable agriculture', 'Increasing food prices and reducing crop yields', 'None of the above', 'A', 'A', 'Các tác giả đề xuất một loạt các giải pháp để giảm thiểu tác động của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu, bao gồm việc áp dụng các phương pháp nông nghiệp có khả năng chống chịu với biến đổi khí hậu và phát triển các giống cây trồng có khả năng chống chịu với khí hậu.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Review of ''The Impact of Climate Change on Global Food Systems''' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'What is a limitation of the book ''The Impact of Climate Change on Global Food Systems''?', 'The authors'' focus on the global North and their neglect of the experiences of small-scale farmers in the global South', 'The book''s emphasis on technological solutions to climate change', 'The lack of data on the impact of climate change on global food systems', 'None of the above', 'A', 'A', 'Một hạn chế của sách ''Ảnh hưởng của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu'' là sự tập trung của tác giả vào khu vực Bắc bán cầu và sự bỏ qua kinh nghiệm của các nông dân nhỏ ở khu vực Nam bán cầu.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Review of ''The Impact of Climate Change on Global Food Systems''' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'What is the tone of the book ''The Impact of Climate Change on Global Food Systems''?', 'Positive and optimistic', 'Critical and analytical', 'Neutral and objective', 'Negative and pessimistic', 'B', 'B', 'Tone của sách ''Ảnh hưởng của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu'' là nghiêm túc và phân tích.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'A Critical Review of ''The Impact of Climate Change on Global Food Systems''' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Who is the book ''The Impact of Climate Change on Global Food Systems'' intended for?', 'Policymakers and researchers working to address the challenges posed by climate change', 'Small-scale farmers and agricultural practitioners', 'Business leaders and investors', 'None of the above', 'A', 'A', 'Sách ''Ảnh hưởng của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu'' được viết cho các chính sách gia và nghiên cứu viên đang làm việc để giải quyết thách thức do biến đổi khí hậu gây ra.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'The Psychological Case Study of John Doe', 'C1', 'John Doe, a 35-year-old marketing executive, had been experiencing symptoms of anxiety and depression for several months. He would often feel overwhelmed by his workload and struggled to sleep at night. Despite his best efforts, he found it difficult to concentrate and make decisions. His relationships with his family and friends began to suffer as a result of his increasing irritability and mood swings.

A comprehensive psychological case study was conducted to understand the underlying causes of John''s symptoms. The study revealed that John had a history of trauma in his childhood, which had led to the development of anxiety and depression. The study also found that John''s coping mechanisms, such as substance abuse and avoidance, were exacerbating his symptoms.

The case study recommended a combination of psychotherapy and medication to help John manage his symptoms. The therapy focused on teaching John coping skills, such as mindfulness and problem-solving, to deal with stress and anxiety. The medication helped to regulate John''s mood and reduce his symptoms of depression.

After several months of treatment, John began to notice significant improvements in his mental health. He was able to sleep better, concentrate more effectively, and make decisions with greater ease. His relationships with his family and friends began to improve, and he felt more confident and self-assured.

The case study of John Doe highlights the importance of seeking professional help for mental health issues. It also underscores the need for a comprehensive approach to treatment, which includes a combination of psychotherapy and medication. By working together with a mental health professional, individuals can develop the skills and strategies needed to manage their symptoms and improve their overall well-being.', 'Vietnamese Translation:
Bản nghiên cứu tâm lý toàn diện của John Doe,

John Doe, một người quản lý marketing 35 tuổi, đã trải qua các triệu chứng lo âu và trầm cảm trong vài tháng. Anh thường cảm thấy quá tải với khối lượng công việc và khó ngủ vào ban đêm. Mặc dù đã cố gắng hết sức, nhưng anh vẫn khó tập trung và đưa ra quyết định. Các mối quan hệ với gia đình và bạn bè của anh bắt đầu bị ảnh hưởng do tính khí ngày càng tồi tệ và nhịp điệu cảm xúc của anh.

Một bản nghiên cứu tâm lý toàn diện đã được thực hiện để hiểu rõ nguyên nhân sâu xa của các triệu chứng của John. Nghiên cứu cho thấy John có một lịch sử tổn thương trong thời thơ ấu, dẫn đến sự phát triển của lo âu và trầm cảm. Nghiên cứu cũng phát hiện ra rằng các cơ chế đối phó của John, chẳng hạn như lạm dụng chất và tránh né, đã làm trầm trọng thêm các triệu chứng của anh.

Bản nghiên cứu đề xuất sự kết hợp giữa liệu pháp tâm lý và thuốc để giúp John kiểm soát các triệu chứng. Liệu pháp tập trung vào việc dạy John các kỹ năng đối phó, chẳng hạn như tâm trí hiện tại và giải quyết vấn đề, để đối phó với căng thẳng và lo âu. Thuốc giúp điều chỉnh tâm trạng và giảm các triệu chứng trầm cảm.

Sau vài tháng điều trị, John bắt đầu nhận thấy những cải thiện đáng kể về sức khỏe tâm thần của mình. Anh có thể ngủ ngon hơn, tập trung tốt hơn và đưa ra quyết định một cách dễ dàng hơn. Các mối quan hệ với gia đình và bạn bè của anh bắt đầu được cải thiện, và anh cảm thấy tự tin và tự chủ hơn.

Bản nghiên cứu của John Doe nhấn mạnh tầm quan trọng của việc tìm kiếm sự giúp đỡ chuyên nghiệp cho các vấn đề sức khỏe tâm thần. Nó cũng nhấn mạnh sự cần thiết của một phương pháp toàn diện để điều trị, bao gồm sự kết hợp giữa liệu pháp tâm lý và thuốc. Bằng cách làm việc cùng với một chuyên gia sức khỏe tâm thần, các cá nhân có thể phát triển các kỹ năng và chiến lược cần thiết để kiểm soát các triệu chứng và cải thiện sức khỏe tổng thể của mình.

Keywords:
anxiety (n): lo âu, depression (n): trầm cảm, trauma (n): tổn thương, coping mechanisms (n): cơ chế đối phó, psychotherapy (n): liệu pháp tâm lý, medication (n): thuốc, mindfulness (n): tâm trí hiện tại, problem-solving (n): giải quyết vấn đề', 20, 5);
