INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Psychological Case Study of John Doe' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Bản nghiên cứu của John Doe nhấn mạnh tầm quan trọng của việc gì?', 'Tìm kiếm sự giúp đỡ chuyên nghiệp cho các vấn đề sức khỏe tâm thần', 'Sự cần thiết của một phương pháp toàn diện để điều trị', 'Cả hai', 'Không có', 'C', 'C', 'Bản nghiên cứu của John Doe nhấn mạnh tầm quan trọng của việc tìm kiếm sự giúp đỡ chuyên nghiệp cho các vấn đề sức khỏe tâm thần và sự cần thiết của một phương pháp toàn diện để điều trị.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Public Health Policy Analysis Report', 'C1', 'The public health policy analysis report highlights the need for a comprehensive approach to addressing the growing concern of obesity in the United States. According to the Centers for Disease Control and Prevention (CDC), the prevalence of obesity among adults has increased by 30% over the past decade, resulting in a significant burden on the healthcare system. The report emphasizes the importance of implementing evidence-based interventions, such as increasing physical activity and improving nutrition, to prevent and manage obesity. Furthermore, the report suggests that policymakers should consider the social determinants of health, including income, education, and access to healthcare, when developing policies to address obesity. By taking a holistic approach, policymakers can effectively address the root causes of obesity and improve public health outcomes. The report also highlights the need for continued research and evaluation to inform policy decisions and ensure the effectiveness of interventions.', 'Vietnamese Translation:
Báo cáo phân tích chính sách sức khỏe công cộng nhấn mạnh nhu cầu cần có một phương pháp toàn diện để đối phó với mối lo ngại về béo phì ở Hoa Kỳ. Theo Trung tâm Kiểm soát và Phòng ngừa Dịch bệnh (CDC), tỷ lệ béo phì ở người lớn đã tăng 30% trong thập kỷ qua, dẫn đến một gánh nặng đáng kể đối với hệ thống y tế. Báo cáo nhấn mạnh tầm quan trọng của việc thực hiện các can thiệp dựa trên bằng chứng, chẳng hạn như tăng cường hoạt động thể chất và cải thiện dinh dưỡng, để ngăn chặn và quản lý béo phì. Hơn nữa, báo cáo đề xuất rằng các nhà lập chính sách nên xem xét các yếu tố quyết định sức khỏe xã hội, bao gồm thu nhập, giáo dục và truy cập vào y tế, khi phát triển các chính sách để đối phó với béo phì. Bằng cách tiếp cận toàn diện, các nhà lập chính sách có thể hiệu quả đối phó với nguyên nhân gốc rễ của béo phì và cải thiện kết quả sức khỏe công cộng. Báo cáo cũng nhấn mạnh nhu cầu tiếp tục nghiên cứu và đánh giá để cung cấp thông tin cho các quyết định chính sách và đảm bảo hiệu quả của các can thiệp.

Keywords:
obesity (n): béo phì, prevalence (n): tỷ lệ xuất hiện, intervention (n): can thiệp, evidence-based (adj): dựa trên bằng chứng, social determinants (n): yếu tố quyết định sức khỏe xã hội, policymaker (n): người lập chính sách, public health (n): sức khỏe công cộng', 20, 5);
