INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Public Health Policy Analysis Report' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'Báo cáo nhấn mạnh tầm quan trọng của việc gì khi phát triển các chính sách để đối phó với béo phì?', 'Thực hiện các can thiệp dựa trên bằng chứng', 'Xem xét các yếu tố quyết định sức khỏe xã hội', 'Tăng cường giáo dục và truy cập vào y tế', 'Tăng cường thu nhập và giáo dục', 'B', 'B', 'Báo cáo nhấn mạnh tầm quan trọng của việc xem xét các yếu tố quyết định sức khỏe xã hội khi phát triển các chính sách để đối phó với béo phì.');
