INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Public Health Policy Analysis Report' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Báo cáo được viết để phục vụ cho mục đích nào?', 'Phát triển các chính sách để đối phó với béo phì', 'Tăng cường giáo dục và truy cập vào y tế', 'Tăng cường thu nhập và giáo dục', 'Tăng cường các yếu tố quyết định sức khỏe xã hội', 'A', 'A', 'Báo cáo được viết để phục vụ cho mục đích phát triển các chính sách để đối phó với béo phì.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'Space Exploration Trends Report', 'C1', 'The latest report on space exploration trends reveals a significant shift in the industry''s focus. Gone are the days of solely pursuing manned missions to Mars. Today, space agencies and private companies are investing heavily in robotic exploration, satellite technology, and space-based solar power. According to the report, the number of robotic missions to Mars has increased by 300% over the past five years, with several countries and companies launching their own robotic probes to the Red Planet. Meanwhile, satellite technology is being used to monitor climate change, track natural disasters, and provide high-speed internet connectivity to remote areas. Space-based solar power, a concept that was once considered science fiction, is now being developed and tested by several companies. This technology has the potential to provide clean and sustainable energy to power entire cities. As the space industry continues to evolve, it is clear that the future of space exploration will be shaped by technological advancements and innovative thinking.', 'Vietnamese Translation:
Báo cáo về xu hướng khám phá không gian cho thấy sự thay đổi đáng kể trong lĩnh vực này. Những ngày đi tìm kiếm con người đến sao hỏa đã qua rồi. Hôm nay, các cơ quan vũ trụ và các công ty tư nhân đang đầu tư mạnh mẽ vào khám phá không gian bằng robot, công nghệ vệ tinh và năng lượng mặt trời dựa trên không gian. Theo báo cáo, số lượng nhiệm vụ khám phá không gian bằng robot đến sao hỏa đã tăng lên 300% trong vòng 5 năm qua, với nhiều quốc gia và công ty đã phóng các tàu thăm dò robot đến hành tinh đỏ. Trong khi đó, công nghệ vệ tinh đang được sử dụng để theo dõi biến đổi khí hậu, theo dõi thiên tai và cung cấp kết nối internet tốc độ cao cho các khu vực xa xôi. Năng lượng mặt trời dựa trên không gian, một ý tưởng từng được coi là khoa học viễn tưởng, hiện đang được phát triển và thử nghiệm bởi nhiều công ty. Công nghệ này có tiềm năng cung cấp năng lượng sạch và bền vững để cung cấp năng lượng cho các thành phố toàn bộ.

Keywords:
space exploration (n): khám phá không gian, robotic mission (n): nhiệm vụ khám phá không gian bằng robot, satellite technology (n): công nghệ vệ tinh, space-based solar power (n): năng lượng mặt trời dựa trên không gian, Mars (n): sao hỏa, climate change (n): biến đổi khí hậu, natural disaster (n): thiên tai', 20, 5);
