INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'Space Exploration Trends Report' ORDER BY id DESC LIMIT 1), 5, 'MULTIPLE_CHOICE', 'C1', 'Xu hướng khám phá không gian hiện nay tập trung vào việc gì?', 'Manned missions đến sao hỏa', 'Khám phá không gian bằng robot', 'Công nghệ vệ tinh', 'Năng lượng mặt trời dựa trên không gian', 'B', 'B', 'Báo cáo cho biết xu hướng khám phá không gian hiện nay tập trung vào việc khám phá không gian bằng robot, công nghệ vệ tinh và năng lượng mặt trời dựa trên không gian.');
INSERT INTO study_contents (type, title, category, body_text, description, duration, questions_count) VALUES ('READING', 'The Impact of Urbanization on Social Relationships', 'C1', 'Urbanization has been a dominant trend in the world for decades. As people move from rural areas to cities in search of better job opportunities and higher standards of living, their social relationships undergo significant changes. One of the most notable effects of urbanization is the decline of traditional social networks. In rural areas, people often rely on their family and community for support and companionship. However, in urban areas, people are more likely to form relationships based on shared interests and proximity. This shift can lead to a sense of loneliness and disconnection among urban dwellers. Furthermore, the fast-paced and competitive nature of city life can make it difficult for people to maintain meaningful relationships. According to a recent study, 60% of urban residents reported feeling isolated or disconnected from their community. To combat this issue, cities are implementing initiatives such as community gardens, public art projects, and social events to foster a sense of community and connection among residents. While urbanization has its drawbacks, it also presents opportunities for social innovation and connection.', 'Vietnamese Translation:
Thành thị hóa đã là một xu hướng thống trị thế giới trong nhiều thập kỷ. Khi người dân di chuyển từ các khu vực nông thôn đến các thành phố để tìm kiếm cơ hội việc làm tốt hơn và mức sống cao hơn, các mối quan hệ xã hội của họ trải qua những thay đổi đáng kể. Một trong những tác động đáng chú ý nhất của thành thị hóa là sự suy giảm của các mạng lưới xã hội truyền thống. Trong các khu vực nông thôn, người dân thường dựa vào gia đình và cộng đồng để được hỗ trợ và đồng hành. Tuy nhiên, trong các khu vực thành thị, người dân có xu hướng hình thành các mối quan hệ dựa trên các sở thích chung và khoảng cách. Điều này có thể dẫn đến cảm giác cô đơn và mất kết nối trong số những cư dân thành thị. Hơn nữa, tính chất nhanh chóng và cạnh tranh của cuộc sống thành phố có thể khiến cho người dân khó duy trì các mối quan hệ có ý nghĩa. Theo một nghiên cứu gần đây, 60% cư dân thành phố đã báo cáo cảm giác cô đơn hoặc mất kết nối với cộng đồng của họ. Để đối phó với vấn đề này, các thành phố đang thực hiện các sáng kiến như vườn cây công cộng, các dự án nghệ thuật công cộng và các sự kiện xã hội để thúc đẩy một cảm giác cộng đồng và kết nối trong số cư dân.

Keywords:
urbanization (n): thành thị hóa, social relationships (n): các mối quan hệ xã hội, traditional social networks (n): các mạng lưới xã hội truyền thống, loneliness (n): cảm giác cô đơn, disconnection (n): mất kết nối, community (n): cộng đồng, social innovation (n): đổi mới xã hội', 20, 5);
