INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Impact of Urbanization on Social Relationships' ORDER BY id DESC LIMIT 1), 3, 'MULTIPLE_CHOICE', 'C1', 'What is the impact of the fast-paced and competitive nature of city life on social relationships?', 'It makes it easier to maintain meaningful relationships', 'It has no impact on social relationships', 'It makes it difficult to maintain meaningful relationships', 'It leads to a sense of community and connection', 'C', 'C', 'Tính chất nhanh chóng và cạnh tranh của cuộc sống thành phố có thể khiến cho người dân khó duy trì các mối quan hệ có ý nghĩa.');
INSERT INTO questions (source_type, parent_id, question_number, type, difficulty, question_text, option_a, option_b, option_c, option_d, correct_option, correct_answer, explanation) VALUES ('READING', (SELECT id FROM study_contents WHERE type = 'READING' AND title = 'The Impact of Urbanization on Social Relationships' ORDER BY id DESC LIMIT 1), 4, 'MULTIPLE_CHOICE', 'C1', 'According to a recent study, what percentage of urban residents reported feeling isolated or disconnected from their community?', '40%', '50%', '60%', '70%', 'C', 'C', 'Theo một nghiên cứu gần đây, 60% cư dân thành phố đã báo cáo cảm giác cô đơn hoặc mất kết nối với cộng đồng của họ.');
